window.FICHES = [{"id":"AAH-DEFINITION","question":"Qu'est-ce que l'AAH ?","reponse":"L'AAH (Allocation aux Adultes Handicapés) est une aide financière qui garantit un revenu minimum aux personnes handicapées pour couvrir les dépenses de la vie courante. Elle est attribuée par la CDAPH (Commission des Droits et de l'Autonomie des Personnes Handicapées) et versée par la CAF ou la MSA.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["aah","allocation adultes handicapés","allocation aux adultes handicapés","aide financière handicap","revenu minimum handicap","allocation handicap adulte","c'est quoi aah","définition aah","qu'est-ce que aah","c'est quoi la aah","explique moi l'aah","Pouvez-vous définir l'AAH ?","À quoi correspond l'AAH ?","Je cherche une explication sur l'AAH : de quoi s'agit-il ?","C'est quoi l'AAH ?","Vous pouvez m'expliquer l'AAH ?","Comment présenter l'AAH à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que l'AAH ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que l'AAH ?","Question : qu'est-ce que l'aah ?","Pourriez-vous me donner une définition de l'AAH ?","J'entends parler de l'AAH partout, qu'est-ce que c'est exactement ?"]},{"id":"AAH-CONDITIONS","question":"Qui peut bénéficier de l'AAH ?","reponse":"Pour bénéficier de l'AAH, vous devez : avoir un taux d'incapacité d'au moins 80%, OU entre 50 et 80% avec restrictions substantielles et durables d'accès à l'emploi (minimum 1 an). Vous devez avoir au moins 20 ans (ou 16 ans si non à charge fiscalement), résider de façon stable et régulière en France (plus de 3 mois), et vos ressources ne doivent pas dépasser 12 fois le montant mensuel de l'AAH.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["aah conditions","éligibilité aah","qui peut avoir aah","taux incapacité aah","conditions aah","bénéficier aah","comment obtenir aah conditions","conditions aah conditions","critères aah conditions","qui a droit aah conditions","Quelles personnes peuvent prétendre à l'AAH ?","Quels sont les critères pour bénéficier de l'AAH ?","À qui l'AAH peut-il être accordé ?","C'est pour qui, l'AAH ?","Qui peut y avoir accès : l'AAH ?","Quelles conditions faut-il remplir pour avoir l'AAH ?","Pour une personne de mon entourage, qui peut bénéficier de l'AAH ?","Pouvez-vous répondre par oui ou non à la question suivante : Qui peut bénéficier de l'AAH ?","Question : qui peut beneficier de l'aah ?","Dans quels profils peut-on ouvrir un droit à l'AAH ?","Est-ce envisageable pour ma mère de toucher l'AAH ?"]},{"id":"AAH-DECONJUGALISATION","question":"Comment l'AAH est-elle calculée pour un couple depuis 2023 ?","reponse":"Depuis octobre 2023, l'AAH est déconjugalisée : elle est calculée uniquement en fonction des ressources de la personne handicapée concernée, sans tenir compte des revenus de son conjoint. Cela permet une plus grande autonomie financière pour les personnes en couple.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["aah déconjugalisation","aah conjoint","aah couple","aah revenus conjoint","aah mariage","calcul aah couple","compte revenus aah déconjugalisation","conjoint aah déconjugalisation","marié aah déconjugalisation","Quel est le mode de calcul de l'allocation aux adultes handicapés pour les personnes en couple depuis la réforme de 2023 ?","Depuis 2023, est-ce que les revenus de mon conjoint comptent encore pour mon AAH ?","Mon copain gagne bien sa vie, ça change quoi pour mon AAH maintenant ?","Comment se calcule l'AAH d'une personne mariée depuis la déconjugalisation ?","Le salaire du conjoint est-il encore pris en compte dans le calcul de l'AAH ?","C'est quoi la déconjugalisation de l'AAH ?","Pour un bénéficiaire de l'AAH qui vit en concubinage, quelles ressources sont retenues depuis octobre 2023 ?","Coment est calculer l'AAH quand on vit en couple maintenant ?","Est-ce que l'AAH dépend encore des revenus du foyer quand on vit à deux ?","Ma femme et moi, on vit ensemble : depuis la réforme, mon allocation adulte handicapé est calculée comment ?"]},{"id":"AAH-DEMARCHES","question":"Comment demander l'AAH ?","reponse":"Pour demander l'AAH : 1) Remplissez le formulaire Cerfa n°15692*01, 2) Joignez un certificat médical de moins de 12 mois, une photocopie de votre pièce d'identité, un justificatif de domicile, 3) Déposez le dossier en main propre, par courrier ou en ligne auprès de votre MDPH. Le délai de traitement est de 4 mois maximum. L'AAH est versée à partir du premier jour du mois qui suit le dépôt de la demande.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["demander aah","dossier aah","formulaire aah","déposer demande aah","documents aah","cerfa aah","comment faire demander aah","démarches demander aah","procédure demander aah","où demander demander aah","Quelles démarches effectuer pour demander l'AAH ?","Comment déposer une demande de l'AAH ?","Quel est le parcours pour obtenir l'AAH ?","Je dois faire une demande de l'AAH : par où commencer ?","C'est quoi la procédure pour demander l'AAH ?","À qui faut-il adresser une demande de l'AAH ?","Pour une personne de mon entourage, comment demander l'AAH ?","Pouvez-vous répondre par oui ou non à la question suivante : Comment demander l'AAH ?","Question : comment demander l'aah ?","Quelles formalités prévoir pour obtenir l'AAH ?"]},{"id":"AAH-DUREE","question":"Pendant combien de temps l'AAH est-elle accordée ?","reponse":"La durée d'attribution de l'AAH dépend de votre taux d'incapacité : avec un taux d'au moins 80%, l'AAH est accordée pour 1 à 10 ans, voire à vie si votre handicap n'est pas évolutif. Avec un taux entre 50 et 80%, elle est attribuée pour 1 à 5 ans. L'AAH est versée jusqu'à la retraite si les conditions sont maintenues.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["durée aah","attribution aah","renouvellement aah","combien de temps aah","aah à vie","renouveler aah","durée durée aah","combien de temps durée aah","renouvelable durée aah","Quelle est la durée d'attribution de l'AAH est-elle accordée ?","Pour quelle période l'AAH est-elle accordée est-il accordé ?","Combien de temps peut-on conserver l'AAH est-elle accordée ?","l'AAH est-elle accordée est accordé pour combien de temps ?","Quelle durée est prévue pour l'AAH est-elle accordée ?","Quand faut-il renouveler l'AAH est-elle accordée ?","Pour une personne de mon entourage, pendant combien de temps l'AAH est-elle accordée ?","Pouvez-vous répondre par oui ou non à la question suivante : Pendant combien de temps l'AAH est-elle accordée ?","Question : pendant combien de temps l'aah est-elle accordee ?","Kel est la durée de l'AAH est-elle accordée ?"]},{"id":"AAH-CUMUL","question":"Peut-on cumuler l'AAH avec d'autres aides ?","reponse":"L'AAH peut être cumulée avec : un salaire sous conditions, la PCH (Prestation de Compensation du Handicap), la MVA (Majoration pour la Vie Autonome), des rémunérations de formation, le RSA (déductible), et une pension retraite si votre taux d'incapacité est d'au moins 80% et que la retraite est inférieure à l'AAH. Le cumul avec l'ASS (Allocation de Solidarité Spécifique) est impossible, sauf pour les anciens bénéficiaires avant 2017 (maximum 10 ans).","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["aah cumul","cumuler aah","aah avec autre aide","aah et salaire","aah et pch","aah et travail","peut-on cumuler aah cumul","compatible aah cumul","en même temps aah cumul","si je touche l'aah j'ai droit au rsa","travailler et toucher l'aah","si je trouve un emploi je perds l'aah","L'allocation aux adultes handicapés est-elle compatible avec d'autres prestations sociales ?","Je touche l'AAH, est-ce que j'ai le droit à d'autres allocations en plus ?","On peut toucher l'AAH et le RSA en même temps ?","Quelles prestations est-il possible de percevoir en même temps que l'AAH ?","Un bénéficiaire de l'AAH peut-il aussi recevoir une pension d'invalidité ou des APL ?","Le cumul de l'AAH avec un salaire ou une autre aide est-il autorisé ?","L'AAH vient-elle en complément des autres aides ou à leur place ?","Avec l'AAH, quelles autres allocations on peut avoir ?","L'AAH et la PCH, c'est cumulabe ?","Quelles sont les règles de cumul entre l'AAH et les autres ressources ?"]},{"id":"PCH-DEFINITION","question":"Qu'est-ce que la PCH ?","reponse":"La PCH (Prestation de Compensation du Handicap) est une aide financière destinée à compenser la perte d'autonomie dans la vie quotidienne et sociale. Elle est versée par le conseil départemental et accordée par la CDAPH. La PCH finance cinq catégories de dépenses : aide humaine, aides techniques, aménagements (logement, véhicule, transport), dépenses exceptionnelles, et aide animalière.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["pch","prestation compensation handicap","prestation compensatoire handicap","aide autonomie","compensation handicap","aide pch","pch pch","c'est quoi pch","définition pch","qu'est-ce que pch","aide payer loyer pch","aide logement pch","aide domicile pch","la pch c'est quoi","explique moi la pch","Pouvez-vous définir la PCH ?","À quoi correspond la PCH ?","Je cherche une explication sur la PCH : de quoi s'agit-il ?","C'est quoi la PCH ?","Vous pouvez m'expliquer la PCH ?","Comment présenter la PCH à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que la PCH ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que la PCH ?","Question : qu'est-ce que la pch ?","Pourriez-vous me donner une définition de la PCH ?","On me parle souvent de la PCH, à quoi ça correspond ?"]},{"id":"PCH-CONDITIONS","question":"Qui peut bénéficier de la PCH ?","reponse":"Pour bénéficier de la PCH adulte : avoir moins de 60 ans (dérogations possibles), présenter une difficulté absolue pour une activité ou deux difficultés graves parmi 20 activités référencées, durant depuis au moins 1 an ou étant définitive, et résider en France de façon stable et régulière. Aucune condition de ressources n'est exigée pour l'attribution.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["pch conditions","éligibilité pch","qui peut avoir pch","critères pch","bénéficier pch","pch handicap","comment obtenir pch conditions","conditions pch conditions","critères pch conditions","qui a droit pch conditions","Quelles personnes peuvent prétendre à la PCH ?","Quels sont les critères pour bénéficier de la PCH ?","À qui la PCH peut-il être accordé ?","C'est pour qui, la PCH ?","Qui peut y avoir accès : la PCH ?","Quelles conditions faut-il remplir pour avoir la PCH ?","Pour une personne de mon entourage, qui peut bénéficier de la PCH ?","Pouvez-vous répondre par oui ou non à la question suivante : Qui peut bénéficier de la PCH ?","Question : qui peut beneficier de la pch ?","Dans quels profils peut-on ouvrir un droit à la PCH ?","Est-ce que ce serait possible pour mon père d'avoir la PCH ?"]},{"id":"PCH-MONTANTS","question":"Quel est le montant de la PCH ?","reponse":"Le taux de prise en charge de la PCH dépend de vos ressources : si vos ressources sont inférieures à 30 915,30 € par an, la prise en charge est de 100%. Si vos ressources sont supérieures à 30 915,30 € par an, la prise en charge est de 80%. Important : les revenus professionnels et pensions de retraite ne sont pas comptabilisés. La PCH est exonérée d'impôts et non récupérable sur succession.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["pch montant","pch combien","montant pch","pch ressources","taux prise charge pch","calcul pch","combien pch montant","montant pch montant","argent pch montant","prix pch montant","Combien représente la PCH ?","Quelle somme peut-on percevoir au titre de la PCH ?","Quel montant est prévu pour la PCH ?","C'est combien, la PCH ?","Comment connaître le montant de la PCH ?","À combien s'élève la PCH ?","Pour une personne de mon entourage, quel est le montant de la PCH ?","Pouvez-vous répondre par oui ou non à la question suivante : Quel est le montant de la PCH ?","Question : quel est le montant de la pch ?","Quelle valeur financière correspond à la PCH ?"]},{"id":"PCH-TYPES","question":"Quels types de dépenses la PCH peut-elle financer ?","reponse":"La PCH couvre cinq types de dépenses : 1) Aide humaine (rémunération d'une personne pour assistance), 2) Aides techniques (matériel spécifique adapté), 3) Aménagement (logement, véhicule, frais de transport supplémentaires), 4) Dépenses exceptionnelles (frais spécifiques liés au handicap), 5) Aide animalière. Depuis 2021, il existe aussi la PCH Parentalité pour les parents handicapés avec enfants de moins de 7 ans.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["types pch","catégories pch","pch aide humaine","pch technique","pch aménagement","pch transport","quels types types pch","catégories types pch","pour quoi types pch","Que permet de prendre en charge la prestation de compensation du handicap ?","La PCH, ça rembourse quoi exactement ?","Quels frais sont couverts par la PCH ?","À quoi sert concrètement la PCH ?","La PCH couvre-t-elle aussi l'aménagement du logement ou du véhicule ?","Quels sont les différents éléments de la prestation de compensation ?","À quelles fins une personne handicapée peut-elle utiliser sa PCH ?","Qu'est-ce qu'on peut payer avec la PCH ?","Quelles dépences sont prises en charge par la PCH ?","Est-ce que la PCH peut servir à payer une aide à domicile ?"]},{"id":"PCH-DEMARCHES","question":"Comment demander la PCH ?","reponse":"Pour demander la PCH : 1) Remplissez le formulaire Cerfa n°15692*01, 2) Joignez une pièce d'identité, un justificatif de domicile, et un certificat médical de moins d'1 an, 3) Déposez le dossier auprès de votre MDPH (en ligne, par courrier ou à l'accueil). La PCH est attribuée pour une durée minimum d'1 an, maximum de 10 ans, et sans limite si votre handicap n'est pas susceptible d'amélioration.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["demander pch","dossier pch","formulaire pch","déposer demande pch","documents pch","cerfa pch","comment faire demander pch","démarches demander pch","procédure demander pch","où demander demander pch","Quelles démarches effectuer pour demander la PCH ?","Comment déposer une demande de la PCH ?","Quel est le parcours pour obtenir la PCH ?","Je dois faire une demande de la PCH : par où commencer ?","C'est quoi la procédure pour demander la PCH ?","À qui faut-il adresser une demande de la PCH ?","Pour une personne de mon entourage, comment demander la PCH ?","Pouvez-vous répondre par oui ou non à la question suivante : Comment demander la PCH ?","Question : comment demander la pch ?","Quelles formalités prévoir pour obtenir la PCH ?"]},{"id":"PCH-CUMUL","question":"Peut-on cumuler la PCH avec d'autres aides ?","reponse":"La PCH est cumulable avec l'AAH, l'AEEH, le RSA, et les allocations logement. Elle n'est pas cumulable avec le complément AEEH, sauf pour les aménagements et les surcoûts de transport. En cas d'éligibilité à la fois à l'AEEH avec complément et à la PCH, vous devrez faire un choix entre les deux prestations.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["pch cumul","cumuler pch","pch avec autre aide","pch et aah","pch et aeeh","pch compatible","peut-on cumuler pch cumul","compatible pch cumul","en même temps pch cumul","La prestation de compensation du handicap est-elle compatible avec d'autres prestations ?","J'ai la PCH, je peux toucher autre chose en plus ?","La PCH et l'APA, on peut avoir les deux ?","Quelles aides est-il possible de percevoir en plus de la PCH ?","Le bénéficiaire de la PCH peut-il aussi percevoir une autre allocation ?","Le cumul de la PCH avec l'ACTP ou la MTP est-il autorisé ?","Quelles sont les règles de cumul de la PCH ?","Est-ce que la PCH s'ajoute à mes autres prestations ?","On peut cumuller la PCH et une pension d'invalidité ?","Si je touche déjà la PCH, quelles autres allocations me restent accessibles ?"]},{"id":"RQTH-DEFINITION","question":"Qu'est-ce que la RQTH ?","reponse":"La RQTH (Reconnaissance de la Qualité de Travailleur Handicapé) est une décision administrative permettant aux personnes en situation de handicap de bénéficier de mesures favorisant leur insertion professionnelle et leur maintien dans l'emploi. Elle ouvre l'accès à des aménagements de poste, des formations prioritaires, et une protection renforcée en cas de licenciement.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["rqth","reconnaissance qualité travailleur handicapé","travailleur handicapé","statut travailleur handicapé","reconnaissance handicap travail","c'est quoi rqth","définition rqth","qu'est-ce que rqth","rqth c koi","qu'est ce qu'une rqth","Pouvez-vous définir la RQTH ?","À quoi correspond la RQTH ?","Je cherche une explication sur la RQTH : de quoi s'agit-il ?","C'est quoi la RQTH ?","Vous pouvez m'expliquer la RQTH ?","Comment présenter la RQTH à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que la RQTH ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que la RQTH ?","Question : qu'est-ce que la rqth ?","Pourriez-vous me donner une définition de la RQTH ?","Je vois le sigle RQTH partout, ça veut dire quoi ?"]},{"id":"RQTH-AVANTAGES","question":"Quels sont les avantages de la RQTH ?","reponse":"Les avantages de la RQTH en emploi : aménagements des conditions de travail (horaires, postes adaptés), accès à du matériel spécialisé financé par l'Agefiph ou le Fiphfp, protection renforcée en cas de licenciement (préavis doublé, jusqu'à 3 mois), accompagnement au maintien dans l'emploi par Cap emploi. Pour les demandeurs d'emploi : accès prioritaire aux formations via le CPF, orientation vers dispositifs adaptés, aménagements de concours pour la fonction publique.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["avantages rqth","rqth emploi","rqth bénéfices","amenagements travail","amenager poste","rqth aménagement","rqth protection","rqth formation","adapter poste travail","ergonomie poste","avantages avantages rqth","bénéfices avantages rqth","pourquoi avantages rqth","Qu'apporte la reconnaissance de la qualité de travailleur handicapé ?","La RQTH, ça sert à quoi concrètement ?","Quel est l'intérêt d'avoir une RQTH ?","Quels droits donne la RQTH au travail ?","Avoir la RQTH permet-il d'obtenir un aménagement de poste ?","Pour un salarié, qu'est-ce que la RQTH change dans la pratique ?","Est-ce que ça vaut le coup de demander la RQTH ?","Quels bénéfices un travailleur handicapé tire-t-il de sa RQTH ?","C'est quoi l'intérét de la RQTH ?","La RQTH donne-t-elle accès à des aides pour trouver un emploi ?"]},{"id":"RQTH-CONDITIONS","question":"Qui peut bénéficier de la RQTH ?","reponse":"Pour obtenir la RQTH, vous devez avoir au minimum 16 ans (ou 15 ans si vous êtes en apprentissage ou stage), et présenter une limitation d'obtenir ou de conserver un emploi en raison d'une dégradation physique, sensorielle, mentale ou psychique. Il n'y a pas de taux d'incapacité minimum requis, c'est l'impact sur l'emploi qui est évalué par la CDAPH.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["rqth conditions","éligibilité rqth","qui peut avoir rqth","critères rqth","obtenir rqth","demander rqth","comment obtenir rqth conditions","conditions rqth conditions","critères rqth conditions","qui a droit rqth conditions","Quelles personnes peuvent prétendre à la RQTH ?","Quels sont les critères pour bénéficier de la RQTH ?","À qui la RQTH peut-il être accordé ?","C'est pour qui, la RQTH ?","Qui peut y avoir accès : la RQTH ?","Quelles conditions faut-il remplir pour avoir la RQTH ?","Pour une personne de mon entourage, qui peut bénéficier de la RQTH ?","Pouvez-vous répondre par oui ou non à la question suivante : Qui peut bénéficier de la RQTH ?","Question : qui peut beneficier de la rqth ?","Dans quels profils peut-on ouvrir un droit à la RQTH ?","Est-il envisageable pour mon frère d'obtenir la RQTH ?"]},{"id":"RQTH-DEMARCHES","question":"Comment demander la RQTH ?","reponse":"Pour demander la RQTH : 1) Remplissez le formulaire Cerfa 15692*01, 2) Joignez un certificat médical (Cerfa 15695*01), votre carte d'identité, un justificatif de domicile, 3) Complétez la section situation professionnelle et cochez la case RQTH, 4) Déposez le dossier auprès de votre MDPH (par courrier, en ligne ou directement). La RQTH est accordée pour 1 à 10 ans renouvelables, ou sans limite de durée si votre handicap n'évoluera jamais.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["demander rqth","dossier rqth","formulaire rqth","déposer demande rqth","documents rqth","obtention rqth","comment faire demander rqth","démarches demander rqth","procédure demander rqth","où demander demander rqth","Quelles démarches effectuer pour demander la RQTH ?","Comment déposer une demande de la RQTH ?","Quel est le parcours pour obtenir la RQTH ?","Je dois faire une demande de la RQTH : par où commencer ?","C'est quoi la procédure pour demander la RQTH ?","À qui faut-il adresser une demande de la RQTH ?","Pour une personne de mon entourage, comment demander la RQTH ?","Pouvez-vous répondre par oui ou non à la question suivante : Comment demander la RQTH ?","Question : comment demander la rqth ?","Quelles formalités prévoir pour obtenir la RQTH ?"]},{"id":"RQTH-DUREE","question":"Pendant combien de temps la RQTH est-elle accordée ?","reponse":"La RQTH est accordée pour une durée de 1 à 10 ans renouvelable. Elle peut être attribuée sans limite de durée si votre handicap n'évoluera jamais. Le renouvellement n'est pas automatique : vous devez en faire la demande 4 mois avant l'expiration, avec un nouveau certificat médical.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["durée rqth","renouvellement rqth","rqth combien temps","rqth à vie","validité rqth","expiration rqth","durée durée rqth","combien de temps durée rqth","renouvelable durée rqth","renouveler durée rqth","Quelle est la durée de validité de la reconnaissance de la qualité de travailleur handicapé ?","La RQTH, c'est valable combien d'années ?","Pour quelle durée attribue-t-on la RQTH ?","Peut-on obtenir la RQTH à vie ?","Jusqu'à quand ma RQTH reste-t-elle valable ?","Au bout de combien d'années faut-il renouveler sa RQTH ?","Est-ce que la RQTH a une date de fin ?","Un travailleur handicapé garde sa RQTH pendant quelle durée ?","C'est quoi la durée de validitée d'une RQTH ?","Quand doit-on redemander la RQTH ?"]},{"id":"AEEH-DEFINITION","question":"Qu'est-ce que l'AEEH ?","reponse":"L'AEEH (Allocation d'Éducation de l'Enfant Handicapé) est une aide financière destinée à compenser les dépenses liées à la situation de handicap de votre enfant de moins de 20 ans. C'est une prestation familiale gérée par la CAF ou la MSA. Elle comprend une allocation de base et peut être complétée par des compléments selon le degré de handicap et les besoins spécifiques.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["aeeh","allocation éducation enfant handicapé","allocation enfant handicapé","aide financière enfant handicapé","prestation enfant handicap","c'est quoi aeeh","définition aeeh","qu'est-ce que aeeh","aeeh ça veut dire quoi","Pouvez-vous définir l'AEEH ?","À quoi correspond l'AEEH ?","Je cherche une explication sur l'AEEH : de quoi s'agit-il ?","C'est quoi l'AEEH ?","Vous pouvez m'expliquer l'AEEH ?","Comment présenter l'AEEH à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que l'AEEH ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que l'AEEH ?","Question : qu'est-ce que l'aeeh ?","Pourriez-vous me donner une définition de l'AEEH ?","On m'a parlé de l'AEEH pour mon enfant, c'est quoi au juste ?"]},{"id":"AEEH-CONDITIONS","question":"Qui peut bénéficier de l'AEEH ?","reponse":"Pour bénéficier de l'AEEH, votre enfant doit : avoir moins de 20 ans, avoir un taux d'incapacité d'au moins 80% (attribution automatique) OU entre 50 et 80% avec accompagnement scolaire adapté, placement en établissement médico-social, ou soins spécifiques. Vous devez résider de façon stable et régulière en France. Si l'enfant travaille (16 ans et plus), ses revenus ne doivent pas dépasser 55% du SMIC brut mensuel.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["aeeh conditions","éligibilité aeeh","qui peut avoir aeeh","critères aeeh","taux incapacité aeeh","bénéficier aeeh","comment obtenir aeeh conditions","conditions aeeh conditions","critères aeeh conditions","qui a droit aeeh conditions","Quelles personnes peuvent prétendre à l'AEEH ?","Quels sont les critères pour bénéficier de l'AEEH ?","À qui l'AEEH peut-il être accordé ?","C'est pour qui, l'AEEH ?","Qui peut y avoir accès : l'AEEH ?","Quelles conditions faut-il remplir pour avoir l'AEEH ?","Pour une personne de mon entourage, qui peut bénéficier de l'AEEH ?","Pouvez-vous répondre par oui ou non à la question suivante : Qui peut bénéficier de l'AEEH ?","Question : qui peut beneficier de l'aeeh ?","Dans quels profils peut-on ouvrir un droit à l'AEEH ?","Serait-il possible pour ma fille de toucher l'AEEH ?"]},{"id":"AEEH-MONTANTS","question":"Quel est le montant de l'AEEH ?","reponse":"À partir du 1er avril 2025, l'allocation de base de l'AEEH est de 151,80 € par mois. Les compléments varient de 113,55 € à 1 288,13 € selon la catégorie (6 catégories). Une majoration pour parent isolé peut être accordée, allant de 61,67 € à 507,58 € selon la catégorie, si l'enfant nécessite une tierce personne et bénéficie d'au moins un complément catégorie 2.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["aeeh montant","aeeh combien","montant aeeh","aeeh allocation base","complément aeeh montant","aeeh argent","combien aeeh montant","montant aeeh montant","argent aeeh montant","prix aeeh montant","Combien représente l'AEEH ?","Quelle somme peut-on percevoir au titre de l'AEEH ?","Quel montant est prévu pour l'AEEH ?","C'est combien, l'AEEH ?","Comment connaître le montant de l'AEEH ?","À combien s'élève l'AEEH ?","Pour une personne de mon entourage, quel est le montant de l'AEEH ?","Pouvez-vous répondre par oui ou non à la question suivante : Quel est le montant de l'AEEH ?","Question : quel est le montant de l'aeeh ?","Quelle valeur financière correspond à l'AEEH ?"]},{"id":"AEEH-DEMARCHES","question":"Comment demander l'AEEH ?","reponse":"Pour demander l'AEEH : 1) Remplissez le formulaire Cerfa n°15692*01, 2) Joignez un certificat médical (Cerfa n°15695*01), une pièce d'identité, un justificatif de domicile, et des documents additionnels si besoin, 3) Déposez le dossier auprès de votre MDPH par courrier, en ligne ou en personne. La durée d'attribution varie : pour un taux de 50-80%, c'est 2 à 5 ans ; pour un taux d'au moins 80%, jusqu'aux 20 ans de l'enfant.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["demander aeeh","dossier aeeh","formulaire aeeh","déposer demande aeeh","documents aeeh","cerfa aeeh","comment faire demander aeeh","démarches demander aeeh","procédure demander aeeh","où demander demander aeeh","Quelles démarches effectuer pour demander l'AEEH ?","Comment déposer une demande de l'AEEH ?","Quel est le parcours pour obtenir l'AEEH ?","Je dois faire une demande de l'AEEH : par où commencer ?","C'est quoi la procédure pour demander l'AEEH ?","À qui faut-il adresser une demande de l'AEEH ?","Pour une personne de mon entourage, comment demander l'AEEH ?","Pouvez-vous répondre par oui ou non à la question suivante : Comment demander l'AEEH ?","Question : comment demander l'aeeh ?","Quelles formalités prévoir pour obtenir l'AEEH ?"]},{"id":"AEEH-CUMUL","question":"Peut-on cumuler l'AEEH avec d'autres aides ?","reponse":"L'AEEH peut être cumulée avec ses compléments et avec l'AJPP (allocation journalière de présence parentale). Concernant la PCH : l'AEEH de base et la PCH sont cumulables, mais les compléments AEEH et la PCH sont incompatibles, sauf pour les aménagements et surcoûts de transport. Un droit d'option AEEH/PCH permet de choisir la solution la plus avantageuse : AEEH + complément, AEEH + PCH, ou AEEH + 3e élément PCH + complément AEEH.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["aeeh cumul","cumuler aeeh","aeeh avec autre aide","aeeh et pch","aeeh et complément","aeeh compatible","peut-on cumuler aeeh cumul","compatible aeeh cumul","en même temps aeeh cumul","L'allocation d'éducation de l'enfant handicapé est-elle compatible avec d'autres prestations ?","On touche l'AEEH pour notre fils, on peut avoir d'autres aides en plus ?","L'AEEH et la PCH en même temps, c'est possible ?","Quelles prestations peut-on percevoir en même temps que l'AEEH ?","Une famille qui reçoit l'AEEH garde-t-elle ses allocations familiales ?","Le cumul de l'AEEH avec l'AJPP est-il possible ?","Quelles sont les règles de cumul de l'AEEH et de ses compléments ?","Est-ce que l'AEEH empêche de toucher d'autres allocations ?","L'AEEH se cumul avec quoi ?","Des parents bénéficiaires de l'AEEH ont-ils droit à d'autres aides pour leur enfant ?"]},{"id":"CMI-INVALIDITE-DEFINITION","question":"Qu'est-ce que la CMI mention invalidité ?","reponse":"La CMI (Carte Mobilité Inclusion) mention 'invalidité' est une carte gratuite qui facilite la vie quotidienne et les déplacements des personnes en situation de handicap présentant une perte d'autonomie importante. Elle offre la priorité d'accès aux places assises dans les transports, aux files d'attente, ainsi que des avantages fiscaux, des réductions tarifaires dans les transports, et le statut de travailleur handicapé sans démarche RQTH supplémentaire.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["cmi invalidité","carte mobilité inclusion invalidité","carte invalidité","carte handicap","cmi handicap","carte priorité handicap","c'est quoi cmi invalidité","définition cmi invalidité","qu'est-ce que cmi invalidité","c'est quoi la cmi","carte mobilité inclusion c'est quoi","Que désigne la carte mobilité inclusion portant la mention invalidité ?","C'est quoi la carte invalidité ?","La CMI invalidité, c'est quoi exactement ?","À quoi correspond la mention invalidité sur la CMI ?","Pouvez-vous définir la CMI mention invalidité ?","Qu'appelle-t-on carte mobilité inclusion invalidité ?","La CMI invalidité est-elle la même chose que l'ancienne carte d'invalidité ?","Ça veut dire quoi, CMI mention invalidité ?","Cest quoi la CMI mension invalidité ?","Ma tante parle de sa CMI invalidité, de quoi s'agit-il ?"]},{"id":"CMI-INVALIDITE-CONDITIONS","question":"Qui peut bénéficier de la CMI mention invalidité ?","reponse":"La CMI mention 'invalidité' est accordée si vous avez un taux d'incapacité d'au moins 80%, OU si vous bénéficiez de la majoration pour tierce personne d'une pension d'invalidité de 3e catégorie. Il n'y a aucune limite d'âge pour faire la demande. Des mentions supplémentaires peuvent être ajoutées : 'besoin d'accompagnement' ou 'cécité' selon votre situation.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["cmi invalidité conditions","éligibilité cmi invalidité","qui peut avoir cmi","taux incapacité cmi","critères cmi invalidité","comment obtenir cmi invalidité conditions","conditions cmi invalidité conditions","critères cmi invalidité conditions","qui a droit cmi invalidité conditions","Quelles sont les conditions d'attribution de la carte mobilité inclusion mention invalidité ?","Il faut quoi pour avoir la carte invalidité ?","Qui a droit à la CMI invalidité ?","À partir de quel taux d'incapacité obtient-on la CMI mention invalidité ?","Avec un taux de 80 %, ai-je droit à la CMI invalidité ?","Une personne en invalidité 3e catégorie peut-elle obtenir la CMI invalidité ?","Faut-il un taux d'au moins 80 % pour la carte invalidité ?","Dans quels cas la CMI mention invalidité est-elle attribuée ?","Quels sont les critaires pour obtenir la CMI invalidité ?","Mon taux est de 50 %, est-ce que je peux prétendre à la carte invalidité ?"]},{"id":"CMI-INVALIDITE-AVANTAGES","question":"Quels sont les avantages de la CMI mention invalidité ?","reponse":"La CMI invalidité offre : la priorité d'accès aux places assises dans les transports en commun, la priorité dans les files d'attente et caisses prioritaires, des avantages fiscaux (notamment 1/2 part supplémentaire pour le calcul de l'impôt sur le revenu), des réductions tarifaires dans les transports (RATP, SNCF, Air France), et le statut de travailleur handicapé sans avoir à faire de démarche RQTH supplémentaire. L'accompagnant bénéficie des mêmes avantages.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["avantages cmi invalidité","cmi invalidité bénéfices","droits cmi","réductions cmi","priorité cmi","fiscalité cmi","avantages avantages cmi invalidité","bénéfices avantages cmi invalidité","droits avantages cmi invalidité","Qu'apporte la carte mobilité inclusion mention invalidité à son titulaire ?","La carte invalidité, ça donne droit à quoi ?","Quels droits ouvre la CMI invalidité ?","Avec la CMI invalidité, a-t-on une demi-part fiscale en plus ?","Quel est l'intérêt d'avoir la CMI mention invalidité ?","La CMI invalidité permet-elle de passer en priorité dans les files d'attente ?","Qu'est-ce qu'on gagne à avoir la carte invalidité ?","Quels avantages un titulaire de la CMI invalidité a-t-il dans les transports ?","Elle sert a quoi la carte d'invalidité ?","Est-ce que la CMI invalidité donne des réductions ?"]},{"id":"CMI-INVALIDITE-DEMARCHES","question":"Comment demander la CMI mention invalidité ?","reponse":"Pour demander la CMI invalidité : 1) Remplissez le formulaire Cerfa n°15692*01 (papier ou en ligne), 2) Joignez votre carte d'identité, un justificatif de domicile, et un certificat médical, 3) Déposez le dossier à la MDPH (en ligne ou par courrier). Après accord, l'Imprimerie nationale vous envoie un courrier d'appel photo. Transmettez votre photo d'identité (moins de 6 mois, format JPEG, 413x531 pixels minimum, 1 Mo maximum). Vous pouvez suivre la fabrication sur www.carte-mobilite-inclusion.fr et recevrez la carte par courrier.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["demander cmi","dossier cmi","formulaire cmi","déposer demande cmi","obtenir cmi","fabrication cmi","comment faire demander cmi","démarches demander cmi","procédure demander cmi","où demander demander cmi","Quelle est la procédure pour obtenir la carte mobilité inclusion mention invalidité ?","Je fais comment pour avoir la carte invalidité ?","Où faut-il déposer la demande de CMI invalidité ?","Quelles démarches effectuer pour obtenir la CMI mention invalidité ?","La demande de CMI invalidité se fait-elle auprès de la MDPH ?","Quels documents fournir pour une demande de carte invalidité ?","Comment un proche peut-il faire la demande de CMI invalidité pour une personne âgée ?","Faut-il remplir un formulaire spécial pour la CMI invalidité ?","Coment faire la demmande de CMI invalidité ?","Est-ce que je peux demander la carte invalidité en ligne ?"]},{"id":"CMI-INVALIDITE-DUREE","question":"Pendant combien de temps la CMI mention invalidité est-elle accordée ?","reponse":"La CMI invalidité est attribuée pour une durée de 1 à 20 ans selon l'évolution de votre handicap. Elle peut être accordée sans limite de durée si votre situation est stable ou si vous bénéficiez de l'APA (groupes 1-2 Aggir). Le renouvellement doit être demandé 4 à 6 mois avant l'expiration. L'ancienne carte d'invalidité reste valide jusqu'au 31 décembre 2026. En cas de perte, vol ou dommage, un duplicata coûte 10 euros.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["durée cmi","validité cmi","renouvellement cmi","cmi combien temps","expiration cmi","cmi à vie","durée durée cmi","combien de temps durée cmi","renouvelable durée cmi","validité durée cmi","carte invalidité encore valable","ancienne carte invalidité remplacée par quoi","ma carte d'invalidité est-elle toujours valable","Quelle est la durée d'attribution de la CMI mention invalidité ?","La carte invalidité, elle est valable combien d'années ?","Pour quelle durée délivre-t-on la carte mobilité inclusion mention invalidité ?","La CMI invalidité peut-elle être attribuée à vie ?","Jusqu'à quand ma CMI invalidité reste-t-elle valide ?","Faut-il renouveler régulièrement la CMI mention invalidité ?","Une personne âgée en GIR 1 garde sa CMI invalidité pendant quelle durée ?","Est-ce que la carte invalidité a une date d'expiration ?","Quelle est la duré de validité de la CMI invalidité ?","Au bout de combien d'années doit-on refaire sa carte invalidité ?"]},{"id":"MDPH-DEFINITION","question":"Qu'est-ce que la MDPH ?","reponse":"La MDPH (Maison Départementale des Personnes Handicapées) est un guichet unique destiné à faciliter les démarches des personnes en situation de handicap. Elle accueille, informe, accompagne et conseille les personnes handicapées et leur famille. C'est auprès de la MDPH que vous déposez toutes vos demandes d'aides et de prestations liées au handicap (AAH, PCH, RQTH, CMI, AEEH, etc.). Chaque département dispose de sa propre MDPH.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["mdph","maison départementale personnes handicapées","maison handicap","mdph rôle","qu'est-ce mdph","organisme handicap","c'est quoi mdph","définition mdph","qu'est-ce que mdph","rôle mdph","Pouvez-vous définir la MDPH ?","À quoi correspond la MDPH ?","Je cherche une explication sur la MDPH : de quoi s'agit-il ?","C'est quoi la MDPH ?","Vous pouvez m'expliquer la MDPH ?","Comment présenter la MDPH à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que la MDPH ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que la MDPH ?","Question : qu'est-ce que la mdph ?","Pourriez-vous me donner une définition de la MDPH ?","On me dit d'aller voir la MDPH, c'est quoi cet organisme ?"]},{"id":"CERFA-15692","question":"Quel formulaire remplir pour une demande MDPH ?","reponse":"Le Cerfa n°15692*01 est le formulaire unique de demande auprès de la MDPH. Il permet de demander l'ensemble des prestations et orientations : AAH, PCH, RQTH, CMI, AEEH, orientation en établissement, etc. Ce formulaire doit être accompagné d'un certificat médical (Cerfa n°15695*01 de moins de 12 mois pour les adultes, ou moins d'1 an pour les enfants), d'une pièce d'identité, et d'un justificatif de domicile.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["cerfa 15692","formulaire mdph","formulaire demande mdph","dossier mdph","formulaire handicap","demande mdph","quel formulaire cerfa 15692","document remplir cerfa 15692","formulaire cerfa 15692","quel cerfa pour la mdph","cerfa 13788 encore valable","quel papier cerfa pour déposer un dossier handicap","Quel est le document officiel à compléter pour saisir la MDPH ?","Je dois remplir quel papier pour faire un dossier MDPH ?","C'est quoi le cerfa pour la MDPH ?","Où trouver le formulaire de demande auprès de la MDPH ?","Le cerfa 15692 est-il obligatoire pour déposer un dossier à la MDPH ?","Quel imprimé faut-il utiliser pour demander une prestation à la MDPH ?","Pour sa première demande, quel formulaire un usager doit-il envoyer à la MDPH ?","Existe-t-il un formulaire unique pour toutes les demandes à la MDPH ?","Ou télécharger le formulère MDPH ?","Quel dossier faut-il compléter pour obtenir une aide de la MDPH ?"]},{"id":"DELAI-TRAITEMENT-MDPH","question":"Quel est le délai de traitement d'une demande MDPH ?","reponse":"Le délai légal de traitement d'une demande auprès de la MDPH est de 4 mois maximum. Passé ce délai sans réponse, votre demande est considérée comme rejetée (vous pouvez alors faire un recours). Dans la pratique, les délais peuvent varier selon les départements et le type de demande. Il est recommandé de déposer votre demande de renouvellement 4 à 6 mois avant l'expiration de vos droits actuels.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["délai mdph","temps traitement mdph","attente mdph","combien temps réponse mdph","durée instruction mdph","combien de temps délai mdph","délai délai mdph","attente délai mdph","quand réponse délai mdph","Combien de temps faut-il pour obtenir une réponse de la MDPH ?","La MDPH met combien de temps pour traiter un dossier ?","En moyenne, quelle est la durée d'instruction d'un dossier à la MDPH ?","Ça prend combien de mois, une demande à la MDPH ?","La MDPH a-t-elle un délai légal pour répondre ?","Au bout de combien de temps la MDPH rend-elle sa décision ?","Pour un dossier déposé en janvier, quand peut-on espérer une décision de la MDPH ?","Est-ce normal d'attendre plus de quatre mois pour une réponse de la MDPH ?","Combien de temps la MDHP met pour répondre ?","Quels délais compter entre le dépôt du dossier et la décision de la CDAPH ?"]},{"id":"TAUX-INCAPACITE","question":"Qu'est-ce que le taux d'incapacité et comment est-il déterminé ?","reponse":"Le taux d'incapacité évalue les limitations d'activité dues au handicap. Il est déterminé par la CDAPH sur la base du certificat médical et du Guide-barème officiel. Seuils clés : moins de 50% = pas de droits MDPH spécifiques ; 50 à 79% = accès à certaines aides sous conditions ; 80% et plus = accès élargi (AAH à taux plein, CMI invalidité...).","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["taux incapacité","taux handicap","pourcentage handicap","80 pourcent handicap","50 pourcent handicap","évaluation handicap","c'est quoi taux incapacité","comment calculé taux incapacité","qui détermine taux incapacité","Que représente le taux d'incapacité fixé par la MDPH, et selon quelle méthode ?","Le taux d'incapacité, c'est quoi et ça se calcule comment ?","Comment la MDPH évalue-t-elle le taux d'incapacité ?","Que signifie un taux d'incapacité de 50 % ou de 80 % ?","Le taux d'incapacité est-il fixé à partir d'un barème officiel ?","Qui décide du taux d'incapacité d'une personne handicapée ?","Sur quels critères repose l'évaluation du taux d'incapacité ?","Pour un enfant, comment son pourcentage d'incapacité est-il établi ?","Le tau d'incapacité, ça veut dire quoi ?","Est-ce que le médecin traitant fixe lui-même le taux d'incapacité ?"]},{"id":"MVA-DEFINITION","question":"Qu'est-ce que la MVA ?","reponse":"La MVA (Majoration pour la Vie Autonome) est une aide financière permettant aux personnes handicapées vivant en logement indépendant de financer une partie des dépenses liées à leur handicap. Elle complète l'AAH et son montant forfaitaire est de 104,77 euros par mois.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["mva","majoration vie autonome","majoration pour la vie autonome","complément aah","aide logement handicap","allocation autonomie","c'est quoi mva","définition mva","qu'est-ce que mva","Pouvez-vous définir la MVA ?","À quoi correspond la MVA ?","Je cherche une explication sur la MVA : de quoi s'agit-il ?","C'est quoi la MVA ?","Vous pouvez m'expliquer la MVA ?","Comment présenter la MVA à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que la MVA ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que la MVA ?","Question : qu'est-ce que la mva ?","Pourriez-vous me donner une définition de la MVA ?","J'ai vu le sigle MVA sur un courrier, ça correspond à quoi ?"]},{"id":"MVA-CONDITIONS","question":"Qui peut bénéficier de la MVA ?","reponse":"Pour percevoir la MVA, vous devez remplir 4 critères cumulatifs : 1) Avoir un taux d'incapacité d'au moins 80%, 2) Percevoir l'AAH à taux plein, en complément d'une retraite/pension/rente, ou l'ASI, 3) Ne pas percevoir de revenu d'activité professionnelle, 4) Habiter dans un logement indépendant ET percevoir une aide au logement (APL, ALF ou ALS).","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["mva conditions","éligibilité mva","qui peut avoir mva","critères mva","bénéficier mva","conditions majoration vie autonome","comment obtenir mva conditions","conditions mva conditions","critères mva conditions","qui a droit mva conditions","Quelles personnes peuvent prétendre à la MVA ?","Quels sont les critères pour bénéficier de la MVA ?","À qui la MVA peut-il être accordé ?","C'est pour qui, la MVA ?","Qui peut y avoir accès : la MVA ?","Quelles conditions faut-il remplir pour avoir la MVA ?","Pour une personne de mon entourage, qui peut bénéficier de la MVA ?","Pouvez-vous répondre par oui ou non à la question suivante : Qui peut bénéficier de la MVA ?","Question : qui peut beneficier de la mva ?","Dans quels profils peut-on ouvrir un droit à la MVA ?","Est-ce envisageable pour ma mère d'avoir la MVA ?"]},{"id":"MVA-DEMARCHES","question":"Comment demander la MVA ?","reponse":"Pour les bénéficiaires de l'AAH, la MVA est attribuée automatiquement par la CAF ou la MSA dès que vous remplissez les conditions, aucune démarche n'est nécessaire. Pour les bénéficiaires de l'ASI (Allocation Supplémentaire d'Invalidité), vous devez remplir le formulaire MDPH et l'envoyer en recommandé à votre MDPH.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["demander mva","dossier mva","obtenir mva","démarches mva","formulaire mva","attribution mva","comment faire demander mva","démarches demander mva","procédure demander mva","automatique demander mva","Quelles démarches effectuer pour demander la MVA ?","Comment déposer une demande de la MVA ?","Quel est le parcours pour obtenir la MVA ?","Je dois faire une demande de la MVA : par où commencer ?","C'est quoi la procédure pour demander la MVA ?","À qui faut-il adresser une demande de la MVA ?","Pour une personne de mon entourage, comment demander la MVA ?","Pouvez-vous répondre par oui ou non à la question suivante : Comment demander la MVA ?","Question : comment demander la mva ?","Quelles formalités prévoir pour obtenir la MVA ?"]},{"id":"MVA-INTERRUPTION","question":"Dans quels cas la MVA est-elle interrompue ?","reponse":"La MVA est interrompue après 60 jours révolus d'hospitalisation, d'hébergement en établissement médico-social ou d'incarcération. Elle reprend automatiquement le 1er du mois suivant votre retour dans un logement indépendant. Le versement est mensuel et effectué par la CAF ou la MSA.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["mva hospitalisation","mva suspension","interruption mva","mva hébergement","mva établissement","arrêt mva","hospitalisation mva hospitalisation","suspension mva hospitalisation","arrêt mva hospitalisation","interrompu mva hospitalisation","Quelles situations entraînent la suppression de la majoration pour la vie autonome ?","Quand est-ce qu'on perd la MVA ?","La MVA peut-elle s'arrêter si on entre en établissement ?","Pour quelles raisons la MVA cesse-t-elle d'être versée ?","Qu'est-ce qui met fin au versement de la MVA ?","Un allocataire de l'AAH qui quitte son logement autonome conserve-t-il sa MVA ?","Est-ce que la MVA continue si je commence à travailler ?","Ma MVA a été suspendue, pourquoi ?","La MVA s'arrète dans quelles situations ?","Quels événements provoquent l'arrêt de la majoration vie autonome ?"]},{"id":"CMI-PRIORITE-DEFINITION","question":"Qu'est-ce que la CMI mention Priorité ?","reponse":"La CMI mention Priorité est une carte gratuite facilitant la vie quotidienne et les déplacements des personnes en perte d'autonomie. Elle permet l'accès prioritaire aux places assises dans les transports publics, aux zones d'attente, aux établissements et événements publics. Elle donne aussi accès aux files prioritaires et caisses prioritaires. L'accompagnant bénéficie des mêmes avantages.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["cmi priorité","carte mobilité inclusion priorité","carte priorité","carte file prioritaire","priorité handicap","carte orange","c'est quoi cmi priorité","définition cmi priorité","qu'est-ce que cmi priorité","Que désigne la carte mobilité inclusion avec la mention priorité ?","C'est quoi la carte priorité ?","La CMI priorité, ça correspond à quoi ?","À quoi renvoie la mention priorité sur la CMI ?","Pouvez-vous définir la CMI mention priorité ?","Qu'appelle-t-on carte de priorité pour personne handicapée ?","La CMI priorité est-elle l'ancienne carte station debout pénible ?","Ça veut dire quoi, CMI mention priorité ?","Cest quoi la CMI prioritée ?","Mon collègue a une CMI priorité, de quoi s'agit-il ?"]},{"id":"CMI-PRIORITE-CONDITIONS","question":"Qui peut bénéficier de la CMI mention Priorité ?","reponse":"La CMI Priorité est accordée si votre taux d'incapacité est inférieur à 80% ET que la station debout est considérée comme difficile (évaluée par l'équipe pluridisciplinaire de la MDPH). Il n'y a pas de limite d'âge ni d'obligation de percevoir d'autres allocations. Important : si vous avez déjà la CMI Invalidité (taux 80%+), il est inutile de demander la CMI Priorité car l'Invalidité inclut déjà tous ces avantages plus les réductions fiscales et tarifaires.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["cmi priorité conditions","éligibilité cmi priorité","qui peut avoir cmi priorité","critères cmi priorité","station debout difficile","comment obtenir cmi priorité conditions","conditions cmi priorité conditions","critères cmi priorité conditions","qui a droit cmi priorité conditions","Quelles sont les conditions d'obtention de la carte mobilité inclusion mention priorité ?","Il faut quoi pour avoir la carte priorité ?","Qui a droit à la CMI priorité ?","La station debout pénible suffit-elle pour obtenir la CMI priorité ?","Avec un taux d'incapacité inférieur à 80 %, puis-je avoir la CMI priorité ?","Une personne qui ne peut pas rester debout longtemps peut-elle prétendre à la CMI priorité ?","À quelles conditions la MDPH accorde-t-elle la mention priorité ?","Quels critères faut-il remplir pour la CMI priorité ?","Qui est éligibe à la carte prioritée ?","Est-ce que j'ai le droit à la CMI priorité si j'ai du mal à marcher ?"]},{"id":"CMI-PRIORITE-DEMARCHES","question":"Comment demander la CMI mention Priorité ?","reponse":"Pour demander la CMI Priorité : 1) Remplissez le formulaire MDPH Cerfa 15692*01, 2) Joignez pièce d'identité, justificatif de domicile, certificat médical, 3) Décrivez votre situation dans la vie quotidienne, 4) Déposez le dossier à votre MDPH (en ligne ou par courrier). La carte est accordée pour 1 à 20 ans ou sans limite selon l'évolution du handicap. Comptez environ 10 jours après approbation pour recevoir la carte de l'Imprimerie nationale.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["demander cmi priorité","dossier cmi priorité","formulaire cmi priorité","obtenir cmi priorité","démarches cmi priorité","comment faire demander cmi priorité","démarches demander cmi priorité","procédure demander cmi priorité","où demander demander cmi priorité","Par quelle procédure obtient-on la carte mobilité inclusion mention priorité ?","Je fais comment pour avoir la carte priorité ?","À quelle adresse envoyer le dossier de CMI priorité ?","Quelles démarches accomplir pour obtenir la CMI mention priorité ?","La demande de CMI priorité passe-t-elle par la MDPH ?","Quelles pièces faut-il fournir pour solliciter la carte priorité ?","Mon grand-père voudrait la CMI priorité, comment doit-il s'y prendre ?","Peut-on faire la demande de carte priorité sur internet ?","Comment on fait la demmande pour la carte priorité ?","Qui dois-je contacter pour lancer une demande de CMI priorité ?"]},{"id":"CMI-STATIONNEMENT-DEFINITION","question":"Qu'est-ce que la CMI Stationnement ?","reponse":"La CMI Stationnement est une carte gratuite permettant à son titulaire de stationner gratuitement et sans limite de durée sur toutes les places de stationnement public, sur la voirie en surface. La carte doit être fixée contre le pare-brise avant du véhicule. Elle est valable dans tous les pays de l'Union européenne et peut être utilisée dans n'importe quel véhicule, que vous en soyez propriétaire, conducteur ou passager.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["cmi stationnement","carte mobilité inclusion stationnement","carte stationnement handicapé","carte gic","stationnement handicap","place handicapé","c'est quoi cmi stationnement","définition cmi stationnement","qu'est-ce que cmi stationnement","Pouvez-vous définir la CMI Stationnement ?","À quoi correspond la CMI Stationnement ?","Je cherche une explication sur la CMI Stationnement : de quoi s'agit-il ?","C'est quoi la CMI Stationnement ?","Vous pouvez m'expliquer la CMI Stationnement ?","Comment présenter la CMI Stationnement à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que la CMI Stationnement ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que la CMI Stationnement ?","Question : qu'est-ce que la cmi stationnement ?","Pourriez-vous me donner une définition de la CMI Stationnement ?"]},{"id":"CMI-STATIONNEMENT-CONDITIONS","question":"Qui peut bénéficier de la CMI Stationnement ?","reponse":"Pour obtenir la CMI Stationnement, vous devez remplir l'un de ces critères : 1) Avoir une mobilité réduite avec un périmètre de marche inférieur à 200 mètres ou besoin systématique d'aide humaine, de prothèse, de canne ou d'un fauteuil roulant, OU 2) Nécessiter un accompagnement pour les déplacements en raison d'altérations mentales, cognitives, psychiques ou visuelles. La difficulté doit être définitive ou durer au moins un an. La CMI Stationnement n'est pas conditionnée par l'attribution d'autres types de CMI.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["cmi stationnement conditions","éligibilité cmi stationnement","qui peut avoir cmi stationnement","périmètre marche","mobilité réduite","critères stationnement","comment obtenir cmi stationnement conditions","conditions cmi stationnement conditions","critères cmi stationnement conditions","qui a droit cmi stationnement conditions","Quelles personnes peuvent prétendre à la CMI Stationnement ?","Quels sont les critères pour bénéficier de la CMI Stationnement ?","À qui la CMI Stationnement peut-il être accordé ?","C'est pour qui, la CMI Stationnement ?","Qui peut y avoir accès : la CMI Stationnement ?","Quelles conditions faut-il remplir pour avoir la CMI Stationnement ?","Pour une personne de mon entourage, qui peut bénéficier de la CMI Stationnement ?","Pouvez-vous répondre par oui ou non à la question suivante : Qui peut bénéficier de la CMI Stationnement ?","Question : qui peut beneficier de la cmi stationnement ?","Dans quels profils peut-on ouvrir un droit à la CMI Stationnement ?","Ce serait envisageable pour ma grand-mère d'avoir la carte de stationnement ?"]},{"id":"CMI-STATIONNEMENT-DEMARCHES","question":"Comment demander la CMI Stationnement ?","reponse":"Pour demander la CMI Stationnement : 1) Remplissez le formulaire MDPH Cerfa 15692*01, 2) Joignez photocopies de carte d'identité, justificatif de domicile, certificat médical, 3) Décrivez votre situation quotidienne, 4) Déposez le dossier à la MDPH (en ligne ou par courrier). Après approbation, l'Imprimerie nationale vous demande une photo d'identité de moins de 6 mois. La carte est attribuée pour 1 à 20 ans ou sans limite de durée. À Paris, créez un ticket virtuel 'Handi' sur Handi'Stat.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["demander cmi stationnement","dossier cmi stationnement","formulaire cmi stationnement","obtenir carte stationnement","démarches stationnement handicapé","comment faire demander cmi stationnement","démarches demander cmi stationnement","procédure demander cmi stationnement","où demander demander cmi stationnement","Quelle est la démarche pour obtenir la carte mobilité inclusion mention stationnement ?","Je fais comment pour avoir la carte de stationnement handicapé ?","Où déposer une demande de macaron handicapé ?","Quelles formalités faut-il accomplir pour obtenir la CMI stationnement ?","La demande de CMI stationnement se fait-elle à la MDPH ?","Quels documents faut-il joindre pour la carte de stationnement ?","Comment un parent peut-il obtenir la carte de stationnement pour son enfant handicapé ?","Peut-on demander la CMI stationnement sans solliciter d'autre prestation ?","Coment avoir la carte stationement handicapé ?","À qui faut-il s'adresser pour la carte de parking handicapé ?"]},{"id":"APA-DEFINITION","question":"Qu'est-ce que l'APA ?","reponse":"L'APA (Allocation Personnalisée d'Autonomie) est une aide destinée aux personnes âgées de 60 ans et plus, en perte d'autonomie, qui nécessitent une assistance pour les actes quotidiens ou une surveillance constante. Elle existe sous deux formes : à domicile et en établissement. La perte d'autonomie se mesure par la grille AGGIR (niveaux GIR 1 à 4).","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["apa","allocation personnalisée autonomie","allocation personnes agees","aide personnes agees","aide autonomie seniors","aide 60 ans","c'est quoi apa","définition apa","qu'est-ce que apa","Pouvez-vous définir l'APA ?","À quoi correspond l'APA ?","Je cherche une explication sur l'APA : de quoi s'agit-il ?","C'est quoi l'APA ?","Vous pouvez m'expliquer l'APA ?","Comment présenter l'APA à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que l'APA ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que l'APA ?","Question : qu'est-ce que l'apa ?","Pourriez-vous me donner une définition de l'APA ?","On me parle de l'APA pour ma mère, qu'est-ce que c'est ?"]},{"id":"APA-MONTANTS","question":"Quel est le montant de l'APA ?","reponse":"Les montants de l'APA au 1er janvier 2026 sont : GIR 1 (perte maximale) 2 080,33€/mois, GIR 2 : 1 682,30€/mois, GIR 3 : 1 215,99€/mois, GIR 4 : 811,52€/mois. Un montant forfaitaire d'urgence de 1 040,17€ existe également. Le montant dépend du niveau de perte d'autonomie évalué par la grille AGGIR.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["apa montant","apa combien","montant apa","gir apa","grille aggir","montant gir","combien apa montant","montant apa montant","argent apa montant","gir apa montant","Combien représente l'APA ?","Quelle somme peut-on percevoir au titre de l'APA ?","Quel montant est prévu pour l'APA ?","C'est combien, l'APA ?","Comment connaître le montant de l'APA ?","À combien s'élève l'APA ?","Pour une personne de mon entourage, quel est le montant de l'APA ?","Pouvez-vous répondre par oui ou non à la question suivante : Quel est le montant de l'APA ?","Question : quel est le montant de l'apa ?","Quelle valeur financière correspond à l'APA ?"]},{"id":"APA-CONDITIONS","question":"Qui peut bénéficier de l'APA ?","reponse":"Pour bénéficier de l'APA, vous devez : avoir au minimum 60 ans, être en perte d'autonomie nécessitant une assistance pour les actes quotidiens ou une surveillance constante, et être classé en GIR 1, 2, 3 ou 4 selon la grille AGGIR. L'APA ne peut pas être cumulée avec la PCH. Elle cible spécifiquement les seniors en perte d'autonomie.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["apa conditions","éligibilité apa","qui peut avoir apa","apa 60 ans","grille aggir","gir éligible","comment obtenir apa conditions","conditions apa conditions","critères apa conditions","qui a droit apa conditions","Quelles personnes peuvent prétendre à l'APA ?","Quels sont les critères pour bénéficier de l'APA ?","À qui l'APA peut-il être accordé ?","C'est pour qui, l'APA ?","Qui peut y avoir accès : l'APA ?","Quelles conditions faut-il remplir pour avoir l'APA ?","Pour une personne de mon entourage, qui peut bénéficier de l'APA ?","Pouvez-vous répondre par oui ou non à la question suivante : Qui peut bénéficier de l'APA ?","Question : qui peut beneficier de l'apa ?","Dans quels profils peut-on ouvrir un droit à l'APA ?","Est-ce envisageable pour mon père d'avoir l'APA ?"]},{"id":"APA-DEMARCHES","question":"Comment demander l'APA ?","reponse":"Pour demander l'APA : 1) Procurez-vous le dossier auprès de votre conseil départemental, 2) Remplissez le formulaire avec les pièces justificatives, 3) Déposez le dossier par courrier, 4) Une équipe médico-sociale effectue une évaluation à domicile, 5) Vous recevez le plan d'aide dans les 30 jours. L'évaluation détermine votre niveau GIR et le montant de l'aide.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["demander apa","dossier apa","formulaire apa","déposer demande apa","conseil départemental","évaluation apa","comment faire demander apa","démarches demander apa","procédure demander apa","où demander demander apa","Quelles démarches effectuer pour demander l'APA ?","Comment déposer une demande de l'APA ?","Quel est le parcours pour obtenir l'APA ?","Je dois faire une demande de l'APA : par où commencer ?","C'est quoi la procédure pour demander l'APA ?","À qui faut-il adresser une demande de l'APA ?","Pour une personne de mon entourage, comment demander l'APA ?","Pouvez-vous répondre par oui ou non à la question suivante : Comment demander l'APA ?","Question : comment demander l'apa ?","Quelles formalités prévoir pour obtenir l'APA ?"]},{"id":"PENSION-INVALIDITE-DEFINITION","question":"Qu'est-ce que la pension d'invalidité ?","reponse":"La pension d'invalidité est un revenu de remplacement versé aux salariés, indépendants et agriculteurs en incapacité partielle ou totale de travailler suite à un accident ou maladie non professionnelle. Elle se divise en 3 catégories : catégorie 1 (capacité à travailler), catégorie 2 (incapacité à travailler), catégorie 3 (incapacité + besoin d'assistance d'une tierce personne).","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["pension invalidité","pension d'invalidité","invalidité sécurité sociale","catégorie invalidité","revenu remplacement","incapacité travail","c'est quoi pension invalidité","définition pension invalidité","qu'est-ce que pension invalidité","Pouvez-vous définir la pension d'invalidité ?","À quoi correspond la pension d'invalidité ?","Je cherche une explication sur la pension d'invalidité : de quoi s'agit-il ?","C'est quoi la pension d'invalidité ?","Vous pouvez m'expliquer la pension d'invalidité ?","Comment présenter la pension d'invalidité à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que la pension d'invalidité ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que la pension d'invalidité ?","Question : qu'est-ce que la pension d'invalidite ?","Pourriez-vous me donner une définition de la pension d'invalidité ?","On me parle d'une pension d'invalidité, ça correspond à quoi exactement ?"]},{"id":"PENSION-INVALIDITE-CONDITIONS","question":"Qui peut bénéficier de la pension d'invalidité ?","reponse":"Pour obtenir une pension d'invalidité, conditions médicales : vos capacités de travail doivent être réduites d'au moins deux tiers et votre invalidité doit vous empêcher de gagner plus d'un tiers de votre salaire antérieur. Conditions administratives : être affilié au régime général de Sécurité sociale ou à la MSA depuis au moins 12 mois, avoir une durée de travail/cotisation suffisante, et avoir entre l'âge de travailler et 62 ans.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["pension invalidité conditions","éligibilité pension invalidité","qui peut avoir pension invalidité","capacité travail réduite","deux tiers","affiliation sécurité sociale","comment obtenir pension invalidité conditions","conditions pension invalidité conditions","critères pension invalidité conditions","qui a droit pension invalidité conditions","Quelles personnes peuvent prétendre à la pension d'invalidité ?","Quels sont les critères pour bénéficier de la pension d'invalidité ?","À qui la pension d'invalidité peut-il être accordé ?","C'est pour qui, la pension d'invalidité ?","Qui peut y avoir accès : la pension d'invalidité ?","Quelles conditions faut-il remplir pour avoir la pension d'invalidité ?","Pour une personne de mon entourage, qui peut bénéficier de la pension d'invalidité ?","Pouvez-vous répondre par oui ou non à la question suivante : Qui peut bénéficier de la pension d'invalidité ?","Question : qui peut beneficier de la pension d'invalidite ?","Dans quels profils peut-on ouvrir un droit à la pension d'invalidité ?","Serait-il possible pour mon oncle de toucher une pension d'invalidité ?"]},{"id":"PENSION-INVALIDITE-MONTANTS","question":"Quel est le montant de la pension d'invalidité ?","reponse":"Le montant de la pension d'invalidité dépend de votre catégorie et de votre salaire brut annuel moyen sur les 10 meilleures années. Taux appliqués : Catégorie 1 : 30%, Catégorie 2 : 50%, Catégorie 3 : 50% + majoration pour tierce personne. Un montant minimum mensuel est garanti. La pension est imposable et soumise à CSG, CRDS et Casa.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["pension invalidité montant","pension invalidité combien","catégorie pension","calcul pension invalidité","taux invalidité","majoration tierce personne","combien pension invalidité montant","montant pension invalidité montant","argent pension invalidité montant","catégorie pension invalidité montant","Combien représente la pension d'invalidité ?","Quelle somme peut-on percevoir au titre de la pension d'invalidité ?","Quel montant est prévu pour la pension d'invalidité ?","C'est combien, la pension d'invalidité ?","Comment connaître le montant de la pension d'invalidité ?","À combien s'élève la pension d'invalidité ?","Pour une personne de mon entourage, quel est le montant de la pension d'invalidité ?","Pouvez-vous répondre par oui ou non à la question suivante : Quel est le montant de la pension d'invalidité ?","Question : quel est le montant de la pension d'invalidite ?","Quelle valeur financière correspond à la pension d'invalidité ?"]},{"id":"PENSION-INVALIDITE-CUMUL","question":"Peut-on cumuler la pension d'invalidité avec d'autres aides ?","reponse":"La pension d'invalidité peut être cumulée avec : un revenu d'activité salarié/indépendant, l'ARE (allocation retour emploi), les indemnités journalières maladie, une rente AT-MP, une pension d'invalidité militaire, et l'allocation supplémentaire d'invalidité sous conditions. Elle ne peut PAS être cumulée avec l'AAH à taux plein ni avec une pension de retraite du régime général. À 62 ans, elle est remplacée par une pension de retraite pour inaptitude.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["pension invalidité cumul","cumuler pension invalidité","pension et aah","pension invalidité travail","pension et retraite","cumuls pension","peut-on cumuler pension invalidité cumul","compatible pension invalidité cumul","en même temps pension invalidité cumul","avec pension invalidité cumul","La pension d'invalidité est-elle compatible avec les autres prestations sociales ?","Je touche une pension d'invalidité, j'ai le droit à d'autres aides en plus ?","Pension d'invalidité et AAH, on peut avoir les deux ?","Quelles allocations peut-on percevoir en même temps qu'une pension d'invalidité ?","Un pensionné d'invalidité peut-il continuer à travailler et toucher un salaire ?","Le cumul de la pension d'invalidité avec l'allocation chômage est-il possible ?","Quelles sont les règles de cumul pour une pension d'invalidité de la Sécu ?","Est-ce que ma pension d'invalidité m'empêche de demander l'AAH ?","La pension d'invalidité, on peut la cumulé avec quoi ?","En plus de la pension versée par la CPAM, quelles aides puis-je obtenir ?"]},{"id":"PENSION-INVALIDITE-DEMARCHES","question":"Comment demander la pension d'invalidité ?","reponse":"Pour demander une pension d'invalidité : 1) Téléchargez le formulaire de demande, 2) Remplissez-le, datez et signez, 3) Joignez les documents requis (notification rente AT-MP si applicable, justificatif d'identité, titre de séjour le cas échéant, avis d'imposition), 4) Envoyez le tout à votre organisme d'Assurance maladie compétent. La pension est attribuée à titre provisoire et est révisable selon l'évolution de votre santé.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["demander pension invalidité","dossier pension invalidité","formulaire pension invalidité","déposer demande pension","assurance maladie invalidité","comment faire demander pension invalidité","démarches demander pension invalidité","procédure demander pension invalidité","où demander demander pension invalidité","Quelles démarches effectuer pour demander la pension d'invalidité ?","Comment déposer une demande de la pension d'invalidité ?","Quel est le parcours pour obtenir la pension d'invalidité ?","Je dois faire une demande de la pension d'invalidité : par où commencer ?","C'est quoi la procédure pour demander la pension d'invalidité ?","À qui faut-il adresser une demande de la pension d'invalidité ?","Pour une personne de mon entourage, comment demander la pension d'invalidité ?","Pouvez-vous répondre par oui ou non à la question suivante : Comment demander la pension d'invalidité ?","Question : comment demander la pension d'invalidite ?","Quelles formalités prévoir pour obtenir la pension d'invalidité ?"]},{"id":"OETH-DEFINITION","question":"Qu'est-ce que l'OETH ?","reponse":"L'OETH (Obligation d'Emploi des Travailleurs Handicapés) est un dispositif qui incite les employeurs de 20 salariés et plus à embaucher des travailleurs handicapés à hauteur de 6% de l'effectif total. Depuis le 1er janvier 2020, toutes les entreprises doivent déclarer les travailleurs handicapés via la DSN (Déclaration Sociale Nominative).","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["oeth","obligation emploi travailleurs handicapés","quota handicap entreprise","6 pourcent handicap","obligation emploi handicapés","taux emploi handicap","c'est quoi oeth","définition oeth","qu'est-ce que oeth","Pouvez-vous définir l'OETH ?","À quoi correspond l'OETH ?","Je cherche une explication sur l'OETH : de quoi s'agit-il ?","C'est quoi l'OETH ?","Vous pouvez m'expliquer l'OETH ?","Comment présenter l'OETH à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que l'OETH ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que l'OETH ?","Question : qu'est-ce que l'oeth ?","Pourriez-vous me donner une définition de l'OETH ?"]},{"id":"OETH-SANCTIONS","question":"Que risque un employeur qui n'atteint pas le quota de l'OETH ?","reponse":"Les employeurs qui n'atteignent pas le seuil de 6% de travailleurs handicapés doivent payer une contribution annuelle à l'Agefiph (secteur privé) ou au Fiphfp (secteur public). Cette contribution financière vise à compenser le manquement à l'obligation d'emploi et finance des aides pour l'insertion professionnelle des personnes handicapées.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["oeth sanctions","contribution oeth","agefiph contribution","quota non atteint","sanction quota handicap","pénalité oeth","sanctions oeth sanctions","contribution oeth sanctions","pénalité oeth sanctions","amende oeth sanctions","Quelles sont les conséquences pour une entreprise qui ne respecte pas l'obligation d'emploi des travailleurs handicapés ?","Si une boîte n'a pas 6 % de travailleurs handicapés, elle paie quoi ?","Quelle pénalité s'applique en cas de non-respect de l'OETH ?","Une entreprise en dessous des 6 % doit-elle verser une contribution ?","Comment est calculée la contribution due au titre de l'OETH ?","Quelles sanctions encourt une société qui n'emploie pas assez de salariés handicapés ?","Est-ce qu'un employeur peut être sanctionné s'il n'emploie aucun travailleur handicapé ?","À combien s'élève la contribution Agefiph pour une entreprise qui ne remplit pas son obligation ?","Que se passe-t-il si l'entrprise ne respecte pas l'OETH ?","Le défaut d'emploi de travailleurs handicapés entraîne-t-il une amende pour l'employeur ?"]},{"id":"OETH-AVANTAGES","question":"Quelles aides pour un employeur qui embauche un travailleur handicapé ?","reponse":"Les employeurs peuvent compter différents types de contrats pour respecter l'OETH : CDI/CDD, temps partiel ou complet, contrats d'apprentissage/professionnalisation, stages (si le stagiaire est reconnu travailleur handicapé). Des aides financières sont disponibles pour l'intégration, l'adaptation du poste de travail, le maintien dans l'emploi, la formation et les incitations à l'embauche. Sept catégories de bénéficiaires sont éligibles, dont les titulaires de RQTH, CMI invalidité, AAH, et pensions AT.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["oeth avantages employeur","aides embauche handicap","agefiph aides","aide financière handicap","subvention emploi handicapé","avantages oeth avantages employeur","aides oeth avantages employeur","financements oeth avantages employeur","employeur oeth avantages employeur","De quels soutiens financiers bénéficie une entreprise qui recrute une personne handicapée ?","Si j'embauche quelqu'un avec une RQTH, j'ai droit à quoi comme aide ?","Quelles aides l'Agefiph propose-t-elle aux entreprises qui recrutent des salariés handicapés ?","Recruter un salarié handicapé donne-t-il droit à une prime ?","Quels sont les dispositifs d'aide à l'embauche des personnes en situation de handicap ?","Une entreprise qui doit aménager un poste pour un salarié handicapé peut-elle être aidée ?","Est-ce qu'il existe des aides pour adapter un poste de travail à un salarié handicapé ?","Quel est l'intérêt financier de recruter des personnes handicapées pour une PME ?","Il y a quelles aides a l'embauche d'une personne handicapé ?","L'embauche d'un bénéficiaire de l'obligation d'emploi ouvre-t-elle des aides pour l'employeur ?"]},{"id":"CDAPH-DEFINITION","question":"Qu'est-ce que la CDAPH ?","reponse":"La CDAPH (Commission des Droits et de l'Autonomie des Personnes Handicapées) est l'instance de décision de la MDPH. Elle est composée de représentants du département, de l'État, des organismes de protection sociale, des associations de personnes handicapées, et des établissements et services. C'est elle qui prend les décisions concernant vos droits : AAH, PCH, RQTH, CMI, orientation, taux d'incapacité, etc.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["cdaph","commission droits autonomie","commission mdph","décision mdph","équipe pluridisciplinaire","commission handicap","c'est quoi cdaph","définition cdaph","qui décide cdaph","rôle cdaph","Pouvez-vous définir la CDAPH ?","À quoi correspond la CDAPH ?","Je cherche une explication sur la CDAPH : de quoi s'agit-il ?","C'est quoi la CDAPH ?","Vous pouvez m'expliquer la CDAPH ?","Comment présenter la CDAPH à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que la CDAPH ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que la CDAPH ?","Question : qu'est-ce que la cdaph ?","Pourriez-vous me donner une définition de la CDAPH ?","J'ai reçu un courrier signé de la CDAPH, c'est quoi cet organisme ?"]},{"id":"RECOURS-MDPH","question":"Quels sont les recours possibles contre une décision de la MDPH ?","reponse":"Si vous n'êtes pas d'accord avec une décision de la MDPH, vous avez plusieurs recours : 1) Recours gracieux auprès de la MDPH dans les 2 mois suivant la notification (demande de réexamen), 2) Conciliation auprès d'une personne qualifiée dans les 2 mois, 3) Recours contentieux devant le tribunal administratif ou le pôle social du tribunal judiciaire selon le type de décision, dans les 2 mois. Le délai de 4 mois sans réponse vaut rejet implicite, ouvrant droit à recours.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["recours mdph","contester décision mdph","appel mdph","recours gracieux","tribunal contentieux","contester refus","contester recours mdph","refus recours mdph","pas d'accord recours mdph","recours recours mdph","Comment contester une décision rendue par la CDAPH ?","Je suis pas d'accord avec la MDPH, je peux faire quoi ?","Quelles voies de contestation existent face à un refus de la MDPH ?","Est-il possible de faire appel d'une notification MDPH ?","Que faire si la MDPH refuse ma demande d'AAH ?","Quels moyens un usager a-t-il pour remettre en cause un avis de la MDPH ?","Peut-on saisir le tribunal après un refus de la MDPH ?","Comment se passe la contestation d'une décision MDPH ?","Comment on conteste une notifiction MDPH ?","Est-ce qu'on peut demander à la MDPH de revoir sa décision ?"]},{"id":"PCH-ENFANTS","question":"À quelles conditions un enfant peut-il bénéficier de la PCH ?","reponse":"La PCH pour les moins de 20 ans exige 3 conditions cumulatives : être bénéficiaire de l'AEEH, ouvrir droit à un complément AEEH, et avoir une difficulté absolue pour une activité ou grave pour deux activités parmi 20. Elle couvre aide humaine, aides techniques, aménagements et aide animalière. Les familles ont un droit d'option entre AEEH+complément ou AEEH+PCH, révisable à l'échéance.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["enfant handicape","adolescent handicape","pch moins 20 ans","jeune handicape","mineur handicape","enfant moins 20 ans","pch","pch enfant","pch enfants","pch adolescent","aeeh","complement aeeh","allocation education enfant handicape","choix pch aeeh","droit option","Quels critères un mineur doit-il remplir pour obtenir la prestation de compensation du handicap ?","Mon fils peut avoir la PCH ou c'est réservé aux adultes ?","La PCH est-elle accessible aux enfants handicapés ?","Dans quels cas un enfant a-t-il droit à la PCH ?","Faut-il percevoir l'AEEH pour qu'un enfant obtienne la PCH ?","Comment fonctionne la PCH pour les moins de 20 ans ?","Quelles sont les conditions d'accès à la PCH pour un enfant ?","Est-ce que ma fille de 8 ans peut toucher la PCH ?","La PCH enfant, ça marche comment ?","Un mineur handicapé a t'il droit à la PCH ?"]},{"id":"AESH-DEFINITION","question":"Qu'est-ce qu'un AESH ?","reponse":"L'AESH (Accompagnant des Eleves en Situation de Handicap) a pour mission de favoriser l'autonomie des eleves en situation de handicap. L'AESH peut intervenir en aide humaine individuelle, mutualise ou en appui collectif dans les unites localisees pour l'inclusion scolaire (ULIS). L'attribution d'un AESH est notifiee par la CDAPH. L'AESH travaille en lien etroit avec l'equipe enseignante qui determine ses missions precises en fonction du projet personnalise de scolarisation (PPS) de l'eleve.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["aesh","accompagnant eleves situation handicap","accompagnant scolaire","accompagnant des eleves","eleves en situation handicap","aide scolaire","auxiliaire vie scolaire","avs","accompagnement ecole","aide humaine scolaire","c'est quoi aesh","definition aesh","role aesh aesh","qui accompagne aesh","aide a l'ecole aesh","Que fait un accompagnant d'élèves en situation de handicap ?","C'est quoi une AESH ?","Un AESH, ça sert à quoi à l'école ?","Quel est le rôle d'un AESH auprès d'un élève handicapé ?","L'AESH est-il la même chose que l'ancienne AVS ?","Qu'appelle-t-on un accompagnant d'élève à l'école ?","Ma cousine est AESH, en quoi consiste son métier ?","Pouvez-vous définir le terme AESH ?","Cest quoi un AESH a l'école ?","Est-ce qu'un AESH est un enseignant ?","Qu'est-ce qu'un AESH fait concrètement auprès d'un enfant ?","Pouvez-vous m'expliquer le rôle de la personne qui accompagne les élèves handicapés en classe ?"]},{"id":"PPS-DEFINITION","question":"Qu'est-ce que le PPS ?","reponse":"Le PPS définit les aménagements de la scolarité et les aides répondant aux besoins d'un élève handicapé : matériel pédagogique adapté, aide humaine (AESH), aménagements pédagogiques. La CDAPH décide sur la base de l'évaluation de l'équipe pluridisciplinaire de la MDPH, après demande des parents ou du représentant légal. Le PPS est réévalué chaque année.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["pps","projet personnalise scolarisation","projet scolarisation","scolarisation handicap","amenagements scolaires","adaptations pedagogiques","c'est quoi pps","definition pps","comment obtenir pps","qui decide pps","scolarite enfant handicape pps","rentrer ecole pps","entrer ecole pps","premiere scolarisation pps","inscrire ecole pps","Pouvez-vous définir le PPS ?","À quoi correspond le PPS ?","Je cherche une explication sur le PPS : de quoi s'agit-il ?","C'est quoi le PPS ?","Vous pouvez m'expliquer le PPS ?","Comment présenter le PPS à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que le PPS ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que le PPS ?","Question : qu'est-ce que le pps ?","Pourriez-vous me donner une définition de le PPS ?","L'école me parle d'un PPS pour mon enfant, qu'est-ce que c'est ?"]},{"id":"ULIS-DEFINITION","question":"Qu'est-ce qu'une ULIS ?","reponse":"Les ULIS scolarisent des élèves handicapés en milieu ordinaire, du primaire au lycée, avec un enseignement spécialisé tout en les intégrant partiellement en classe ordinaire. Il existe plusieurs types selon le handicap (cognitif, moteur, visuel, auditif, autisme...). Maximum 12 élèves en ULIS école, 10 au collège/lycée. La CDAPH décide du placement après un GEVA-Sco.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["ulis","unite localisee inclusion scolaire","classe ulis","enseignement adapte","inclusion scolaire","scolarisation collective","c'est quoi ulis","definition ulis","comment integrer ulis","types ulis ulis","difference classe ordinaire ulis","Que désigne une unité localisée pour l'inclusion scolaire ?","C'est quoi une classe ULIS ?","Une ULIS, ça fonctionne comment ?","Quel est le principe d'un dispositif ULIS ?","L'ULIS est-elle une classe spécialisée à part ?","Qu'appelle-t-on ULIS école, collège ou lycée ?","Le fils de ma collègue est en ULIS, qu'est-ce que ça veut dire ?","Pouvez-vous définir ce qu'est une ULIS ?","C'est quoi une ulis au collége ?","Est-ce qu'une ULIS accueille tous les enfants handicapés ?","La MDPH propose une orientation en ULIS pour mon enfant, à quoi cela correspond-il ?"]},{"id":"PAI-DEFINITION","question":"Qu'est-ce que le PAI ?","reponse":"Le PAI adapte la vie scolaire d'un enfant ayant un trouble de santé chronique (asthme, allergie, diabète, épilepsie...) SANS reconnaissance de handicap : traitements, régimes, protocoles d'urgence, en temps scolaire et périscolaire. Contrairement au PPS, il ne couvre pas les aménagements pédagogiques. Il est élaboré par le directeur d'établissement avec le médecin scolaire, l'infirmier et la famille.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["pai","projet accueil individualise","projet accueil","maladie chronique","allergie alimentaire","traitement medical ecole","protocole sante","c'est quoi pai","definition pai","difference pps pai","qui decide pai","comment obtenir pai","Pouvez-vous définir le PAI ?","À quoi correspond le PAI ?","Je cherche une explication sur le PAI : de quoi s'agit-il ?","C'est quoi le PAI ?","Vous pouvez m'expliquer le PAI ?","Comment présenter le PAI à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que le PAI ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que le PAI ?","Question : qu'est-ce que le pai ?","Pourriez-vous me donner une définition de le PAI ?"]},{"id":"ESAT-DEFINITION","question":"Qu'est-ce qu'un ESAT ?","reponse":"L'ESAT est une structure médico-sociale en milieu protégé permettant d'exercer une activité professionnelle avec soutien médical et éducatif, pour les personnes dont la capacité de travail est insuffisante pour un emploi ordinaire. Admission dès 20 ans (16 par exception), sur orientation de la CDAPH. Rémunération garantie entre 55,70% et 110,70% du SMIC, cumulable avec une AAH partielle. Pas de licenciement : seule une réorientation met fin au contrat.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["esat","etablissement service accompagnement travail","travail protege","travailleur handicape","milieu protege","activite professionnelle adaptee","c'est quoi esat","definition esat","comment travailler esat","conditions esat","remuneration esat","Que désigne un établissement et service d'aide par le travail ?","C'est quoi un ESAT ?","Un ESAT, ça sert à quoi ?","Quel est le rôle d'un ESAT pour les travailleurs handicapés ?","Un ESAT est-il une entreprise comme les autres ?","Qu'entend-on par travail en ESAT ?","Mon cousin travaille dans un ESAT, en quoi ça consiste ?","Pouvez-vous me définir ce qu'est un ESAT ?","Cest quoi un ESAT exactement ?","Est-ce que l'ESAT est la même chose qu'un CAT ?"]},{"id":"EA-DEFINITION","question":"Qu'est-ce qu'une entreprise adaptée ?","reponse":"L'entreprise adaptée (EA) est une entreprise du milieu ordinaire employant au moins 55% de travailleurs handicapés reconnus (RQTH), actuellement sans emploi. Contrairement à l'ESAT (milieu protégé, contrat d'accompagnement), l'EA propose un contrat de travail classique, au SMIC minimum, avec tous les droits du code du travail, et peut servir de tremplin vers l'emploi ordinaire.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["ea","entreprise adaptee","entreprise handicap","emploi adapte","travail ordinaire handicap","rqth emploi","c'est quoi ea","definition ea","difference esat ea","comment postuler ea","conditions ea","Que désigne le terme d'entreprise adaptée dans le champ du handicap ?","C'est quoi une EA ?","Une entreprise adaptée, ça fonctionne comment ?","Quel est le principe d'une EA pour les travailleurs handicapés ?","Une entreprise adaptée fait-elle partie du milieu ordinaire de travail ?","Qu'appelle-t-on EA ou entreprise adaptée ?","Ma sœur a trouvé un poste dans une entreprise adaptée, qu'est-ce que c'est ?","Pouvez-vous me définir ce qu'est une EA ?","Cest quoi une entrepise adaptée ?","Est-ce qu'une entreprise adaptée embauche uniquement des personnes avec une RQTH ?"]},{"id":"ESRP-DEFINITION","question":"Qu'est-ce qu'un ESRP ?","reponse":"L'ESRP évalue, oriente et forme les personnes handicapées vers un projet professionnel : bilans, formations qualifiantes (10 à 30 mois), accompagnement vers l'emploi, hébergement si besoin. Ouvert dès 16 ans aux demandeurs d'emploi reconnus ou en cours de reconnaissance, aux salariés menacés de perte d'emploi, et aux travailleurs d'ESAT. Pour y accéder : contactez votre MDPH ou l'annuaire Fagerh.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["esrp","etablissement service readaptation professionnelle","readaptation professionnelle","formation professionnelle handicap","reconversion handicap","rehabilitation professionnelle","c'est quoi esrp","definition esrp","qui peut beneficier esrp","comment acceder esrp","duree formation esrp","Que désigne un établissement et service de réadaptation professionnelle ?","C'est quoi un ESRP ?","Un ESRP, ça sert à quoi ?","Quel est le rôle d'un ESRP pour une personne handicapée ?","L'ESRP est-il l'ancien centre de rééducation professionnelle ?","Qu'entend-on par formation en ESRP ?","Mon mari part en ESRP pour une reconversion, de quoi s'agit-il ?","Pouvez-vous définir le sigle ESRP ?","C'est quoi un ERSP ?","Est-ce qu'un ESRP permet de se former à un nouveau métier ?"]},{"id":"RAPO-DEFINITION","question":"Qu'est-ce que le RAPO et dans quel délai le faire ?","reponse":"Le RAPO conteste une décision de refus de la MDPH en demandant un réexamen du dossier : étape obligatoire avant tout tribunal. Délai : 2 mois à partir de la notification de refus, par lettre recommandée avec accusé de réception, adressée à la MDPH (ou au président du conseil départemental pour la CMI). L'autorité dispose de 2 mois pour répondre ; sans réponse ou en cas de rejet, vous pouvez saisir le tribunal sous 2 mois.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["rapo","recours administratif prealable obligatoire","recours amiable","contester decision mdph","refus mdph","contestation cdaph","recours decision","c'est quoi rapo","definition rapo","comment contester rapo","delai recours rapo","apres refus rapo","délai recours décision mdph","comment contester une décision cdaph","j'ai reçu un refus comment je conteste et dans quel délai","À quoi correspond le recours administratif préalable obligatoire et combien de temps a-t-on pour l'engager ?","C'est quoi le RAPO, et j'ai combien de temps pour le faire ?","Que signifie RAPO et quelle est la date limite pour le déposer ?","Le RAPO doit-il être envoyé dans les deux mois après la décision ?","Comment fonctionne le RAPO à la MDPH et jusqu'à quand peut-on le faire ?","Quel est le délai pour former un recours administratif préalable obligatoire ?","Une personne qui conteste une décision MDPH doit-elle d'abord faire un RAPO ?","Est-ce que le RAPO est obligatoire avant d'aller au tribunal ?","Le RAPO c'est quoi et on a combien de temp ?","Pouvez-vous m'expliquer le RAPO et le délai à respecter ?"]},{"id":"GEVA-DEFINITION","question":"Qu'est-ce que le GEVA ?","reponse":"Le GEVA est l'outil standardisé utilisé par l'équipe pluridisciplinaire de la MDPH (médecins, travailleurs sociaux, ergothérapeutes, psychologues) pour évaluer les besoins de compensation d'une personne handicapée à partir de son dossier et de son projet de vie. Cette évaluation sert de base aux décisions de la CDAPH. Une version spécialisée existe pour les enfants scolarisés : le GEVA-Sco.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["geva","guide evaluation besoins compensation","evaluation mdph","equipe pluridisciplinaire","epe","evaluation handicap","besoins compensation","c'est quoi geva","definition geva","qui evalue geva","equipe mdph geva","Pouvez-vous définir le GEVA ?","À quoi correspond le GEVA ?","Je cherche une explication sur le GEVA : de quoi s'agit-il ?","C'est quoi le GEVA ?","Vous pouvez m'expliquer le GEVA ?","Comment présenter le GEVA à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que le GEVA ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que le GEVA ?","Question : qu'est-ce que le geva ?","Pourriez-vous me donner une définition de le GEVA ?"]},{"id":"GEVA-SCO-DEFINITION","question":"Qu'est-ce que le GEVA-Sco ?","reponse":"Le GEVA-Sco adapte le GEVA au contexte scolaire : il centralise les informations sur un élève handicapé pour la MDPH. Deux versions : Première Demande (situation pas encore évaluée, remplie par l'équipe éducative, transmise avec le Cerfa 15692*01) et Réexamen (élève déjà bénéficiaire d'un PPS, rempli en réunion de suivi de scolarisation par l'enseignant référent). Concerne les élèves de la maternelle au lycée, moins de 20 ans.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["geva-sco","geva sco","geva scolaire","evaluation scolaire handicap","pps","projet personnalise scolarisation","equipe educative","enseignant referent","c'est quoi geva-sco","definition geva-sco","qui le remplit geva-sco","pour qui geva-sco","premiere demande geva-sco","reexamen geva-sco","Pouvez-vous définir le GEVA-Sco ?","À quoi correspond le GEVA-Sco ?","Je cherche une explication sur le GEVA-Sco : de quoi s'agit-il ?","C'est quoi le GEVA-Sco ?","Vous pouvez m'expliquer le GEVA-Sco ?","Comment présenter le GEVA-Sco à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que le GEVA-Sco ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que le GEVA-Sco ?","Question : qu'est-ce que le geva-sco ?","Pourriez-vous me donner une définition de le GEVA-Sco ?"]},{"id":"CESU-DEFINITION","question":"Qu'est-ce que le CESU et quel crédit d'impôt pour le handicap ?","reponse":"Le CESU paie et déclare simplement des services à domicile (aide aux actes quotidiens, ménage, accompagnement). Crédit d'impôt de 50% des sommes engagées, plafonné à 6000€ en général, porté à 10000€ pour les personnes avec une carte d'invalidité ou CMI invalidité (taux ≥80%) ou une pension d'invalidité 3e catégorie. L'avance immédiate (Urssaf) déduit le crédit directement de la facture. Les bénéficiaires de la PCH peuvent l'utiliser pour rémunérer leurs aidants professionnels.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["cesu","cheque emploi service universel","emploi service universel","services personne","credit impot handicap","aide domicile","salarie domicile","c'est quoi cesu","definition cesu","avantages fiscaux cesu","montant credit impot cesu","comment utiliser cesu","À quoi sert le chèque emploi service universel et quel avantage fiscal offre-t-il aux personnes handicapées ?","C'est quoi le CESU, et on a droit à une réduction d'impôt avec ?","Comment fonctionne le CESU quand on emploie une aide à domicile du fait de son handicap ?","Le CESU ouvre-t-il droit à un avantage fiscal quand on est handicapé ?","Quel pourcentage des dépenses payées en CESU est remboursé par les impôts ?","Peut-on payer une aide humaine financée par la PCH avec des CESU ?","Une personne handicapée qui embauche un salarié à domicile via le CESU a-t-elle un crédit d'impôt ?","Est-ce que les heures déclarées en CESU sont déductibles des impôts ?","Cest quoi le CESU et l'avantage fiscale pour les handicapés ?","Pouvez-vous m'expliquer le chèque emploi service et les déductions fiscales liées au handicap ?"]},{"id":"AJPP-DEFINITION","question":"Qu'est-ce que l'AJPP ?","reponse":"L'AJPP, versée par la CAF ou la MSA, indemnise un parent qui interrompt son activité pour rester auprès d'un enfant de moins de 20 ans gravement malade, handicapé ou accidenté nécessitant une présence et des soins contraignants. Versée par journée ou demi-journée (limite 22 jours/mois), sur une période maximale de 3 ans. Cumulable avec l'AEEH de base, mais pas avec le complément AEEH : il faut choisir l'option la plus avantageuse.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["ajpp","allocation journaliere presence parentale","allocation presence parentale","enfant gravement malade","interruption activite enfant handicape","conge presence parentale","caf enfant handicape","c'est quoi ajpp","definition ajpp","montant ajpp","conditions ajpp","comment obtenir ajpp","duree ajpp","Pouvez-vous définir l'AJPP ?","À quoi correspond l'AJPP ?","Je cherche une explication sur l'AJPP : de quoi s'agit-il ?","C'est quoi l'AJPP ?","Vous pouvez m'expliquer l'AJPP ?","Comment présenter l'AJPP à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que l'AJPP ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que l'AJPP ?","Question : qu'est-ce que l'ajpp ?","Pourriez-vous me donner une définition de l'AJPP ?"]},{"id":"PAP-DEFINITION","question":"Qu'est-ce que le PAP ?","reponse":"Le PAP organise des aménagements pédagogiques pour un élève dont les difficultés scolaires résultent d'un trouble des apprentissages (dyslexie, dyspraxie, dyscalculie, TDAH...), sans reconnaissance de handicap par la MDPH, après avis du médecin scolaire. Contrairement au PPS (élèves reconnus handicapés) et au PAI (problèmes de santé chroniques), le PAP vise uniquement l'adaptation du suivi du programme scolaire standard. Révisé chaque année.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["pap","plan accompagnement personnalise","plan accompagnement","troubles apprentissages","amenagements pedagogiques","dyslexie","dyspraxie","c'est quoi pap","definition pap","difference pps pap","difference pai pap","comment obtenir pap","Pouvez-vous définir le PAP ?","À quoi correspond le PAP ?","Je cherche une explication sur le PAP : de quoi s'agit-il ?","C'est quoi le PAP ?","Vous pouvez m'expliquer le PAP ?","Comment présenter le PAP à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que le PAP ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que le PAP ?","Question : qu'est-ce que le pap ?","Pourriez-vous me donner une définition de le PAP ?"]},{"id":"PIAL-DEFINITION","question":"Qu'est-ce que le PIAL ?","reponse":"Le PIAL coordonne, au niveau d'un établissement scolaire ou d'un groupe d'établissements, les moyens d'accompagnement humain (AESH) au plus près des besoins des élèves handicapés : il organise les emplois du temps et mutualise les compétences des AESH, qui peuvent ainsi intervenir auprès de plusieurs élèves selon les besoins identifiés dans leurs PPS.","source":{"titre":"education.gouv.fr","url":"https://www.education.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["pial","pole inclusif accompagnement localise","pole inclusif","aesh mutualise","coordination aesh","organisation aesh","c'est quoi pial","definition pial","role pial","lien avec aesh pial","Pouvez-vous définir le PIAL ?","À quoi correspond le PIAL ?","Je cherche une explication sur le PIAL : de quoi s'agit-il ?","C'est quoi le PIAL ?","Vous pouvez m'expliquer le PIAL ?","Comment présenter le PIAL à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que le PIAL ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que le PIAL ?","Question : qu'est-ce que le pial ?","Pourriez-vous me donner une définition de le PIAL ?"]},{"id":"SEGPA-DEFINITION","question":"Qu'est-ce que la SEGPA ?","reponse":"La SEGPA est une section de collège pour élèves en difficulté scolaire grave et persistante, non résolue par les aides habituelles, orientée en fin de CM2 ou de 6e (la CDAPH peut orienter les élèves handicapés). En 6e-5e : enseignement général préparant les bases ; en 4e-3e : formation professionnelle et stages, vers un CAP. Contrairement à l'ULIS, la SEGPA accueille des élèves en difficulté scolaire, avec ou sans handicap reconnu.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["segpa","section enseignement general professionnel adapte","enseignement adapte","college adapte","difficultes scolaires graves","orientation segpa","cap en segpa","c'est quoi segpa","definition segpa","pour qui segpa","difference ulis segpa","comment integrer segpa","Pouvez-vous définir la SEGPA ?","À quoi correspond la SEGPA ?","Je cherche une explication sur la SEGPA : de quoi s'agit-il ?","C'est quoi la SEGPA ?","Vous pouvez m'expliquer la SEGPA ?","Comment présenter la SEGPA à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que la SEGPA ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que la SEGPA ?","Question : qu'est-ce que la segpa ?","Pourriez-vous me donner une définition de la SEGPA ?"]},{"id":"TSA-DEFINITION","question":"Qu'est-ce que les TSA (troubles du spectre autistique) ?","reponse":"Les TSA (troubles du spectre autistique) sont des troubles neurodéveloppementaux affectant la communication socio-émotionnelle, avec des comportements atypiques ou répétitifs ; leur intensité varie beaucoup d'une personne à l'autre, d'où le mot « spectre ». Ce terme remplace l'ancienne appellation TED depuis 2013. Accompagnement possible : AAH/AEEH, scolarisation avec PPS et AESH, aménagements dans le supérieur, emploi adapté, PCH pour les surcoûts liés au handicap.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["tsa","troubles spectre autistique","autisme","autiste","ted","trouble autistique","asperger","handicap autisme","c'est quoi tsa","definition tsa","caracteristiques tsa","diagnostic tsa","accompagnement tsa","Que désignent les troubles du spectre de l'autisme ?","C'est quoi les TSA ?","Le TSA, ça veut dire quoi exactement ?","Comment définit-on un trouble du spectre autistique ?","Le TSA est-il la même chose que l'autisme ?","Quelles caractéristiques regroupe-t-on sous le terme de TSA ?","Le fils de mon amie a un diagnostic de TSA, qu'est-ce que ça signifie ?","Pouvez-vous m'expliquer ce que recouvre le sigle TSA ?","Cest quoi un trouble du spectre autistic ?","Est-ce que le syndrome d'Asperger fait partie des TSA ?","Quels sont les signes qui font penser à un TSA chez un enfant ?"]},{"id":"TND-DEFINITION","question":"Qu'est-ce que les TND (troubles du neuro-développement) ?","reponse":"Les TND regroupent les troubles qui apparaissent tôt dans le développement de l'enfant et touchent le fonctionnement cognitif, moteur, sensoriel ou relationnel : troubles du développement intellectuel, du langage, du spectre autistique (TSA), TDAH, troubles spécifiques des apprentissages (dyslexie, dyscalculie...). Un diagnostic précoce, pluridisciplinaire, est essentiel. Selon la sévérité : suivi médical et paramédical, aménagements scolaires (PAP, PPS) et aides financières (AEEH, PCH).","source":{"titre":"sante.gouv.fr","url":"https://www.sante.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["tnd","troubles neuro developpement","troubles neurodeveloppementaux","developpement enfant","retard developpement","troubles cognitifs","c'est quoi tnd","definition tnd","types tnd","exemples tnd","diagnostic tnd","Que recouvrent les troubles du neurodéveloppement ?","C'est quoi les TND ?","Les TND, ça regroupe quoi comme troubles ?","Comment définit-on un trouble du neurodéveloppement ?","Le TDAH fait-il partie des TND ?","Quels troubles classe-t-on parmi les troubles neurodéveloppementaux ?","Ma nièce a été diagnostiquée TND, qu'est-ce que ça veut dire ?","Pouvez-vous m'expliquer ce que signifie le sigle TND ?","Cest quoi un trouble du neuro dévellopement ?","Est-ce que les troubles dys sont des TND ?","L'école parle d'un trouble du neuro-développement pour mon fils, de quoi s'agit-il ?"]},{"id":"CNSA-DEFINITION","question":"Qu'est-ce que la CNSA ?","reponse":"La CNSA, créée en 2004, finance et anime la politique nationale de l'autonomie : elle participe au financement de l'APA et de la PCH, contribue au budget des MDPH, veille à l'égalité de traitement sur tout le territoire, et anime le réseau (harmonisation des pratiques, information du public). Elle gère un budget annuel de plus de 26 milliards d'euros.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["cnsa","caisse nationale solidarite autonomie","caisse solidarite","financement autonomie","financement mdph","etablissement public handicap","c'est quoi cnsa","definition cnsa","role cnsa","mission cnsa","lien mdph cnsa","Pouvez-vous définir la CNSA ?","À quoi correspond la CNSA ?","Je cherche une explication sur la CNSA : de quoi s'agit-il ?","C'est quoi la CNSA ?","Vous pouvez m'expliquer la CNSA ?","Comment présenter la CNSA à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que la CNSA ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que la CNSA ?","Question : qu'est-ce que la cnsa ?","Pourriez-vous me donner une définition de la CNSA ?"]},{"id":"MSA-DEFINITION","question":"Qu'est-ce que la MSA et quel lien avec le handicap ?","reponse":"La MSA est le 2e régime de protection sociale en France, couvrant les exploitants et salariés agricoles et leurs ayants droit : santé, famille, retraite, accidents du travail. Pour le handicap, elle verse les mêmes prestations que la CAF (AEEH, AAH, PCH, pension d'invalidité, CMI) aux affiliés du régime agricole — seul l'organisme payeur change selon le régime d'affiliation.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["msa","mutualite sociale agricole","regime agricole","securite sociale agricole","agriculteur handicape","regime social agricole","c'est quoi msa","definition msa","role msa","prestations msa","difference caf msa","À quoi correspond la Mutualité sociale agricole et quel rôle joue-t-elle pour les personnes handicapées ?","C'est quoi la MSA, et elle s'occupe du handicap ?","La MSA verse-t-elle l'AAH aux agriculteurs ?","Quel est le rôle de la MSA pour un exploitant agricole handicapé ?","Si je dépends de la MSA, qui me paie mon AAH ?","Que fait la Mutualité sociale agricole en matière de handicap ?","Un salarié agricole en situation de handicap dépend-il de la MSA ou de la CAF ?","Est-ce que la MSA remplace la CAF pour les gens du monde agricole ?","Cest quoi la MSA, son rôle pour les persones handicapées ?","Pouvez-vous m'expliquer ce qu'est la MSA, puis ce qu'elle fait pour les personnes handicapées ?"]},{"id":"FIPHFP-DEFINITION","question":"Qu'est-ce que le FIPHFP ?","reponse":"Le FIPHFP, créé en 2005, collecte les contributions des employeurs publics (État, collectivités, hôpitaux) de 20 agents et plus qui n'atteignent pas leur quota de travailleurs handicapés, et finance en retour l'insertion et le maintien dans l'emploi : aménagement de poste, aides techniques, accompagnement, formation. Il bénéficie aux personnes handicapées employées ou en recherche d'emploi dans le secteur public.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["fiphfp","fonds insertion handicap fonction publique","fiphfp aide","emploi handicap fonction publique","quota handicap fonction publique","contribution fiphfp","c'est quoi fiphfp","definition fiphfp","qui beneficie fiphfp","aides financees fiphfp","comment ca marche fiphfp","Pouvez-vous définir le FIPHFP ?","À quoi correspond le FIPHFP ?","Je cherche une explication sur le FIPHFP : de quoi s'agit-il ?","C'est quoi le FIPHFP ?","Vous pouvez m'expliquer le FIPHFP ?","Comment présenter le FIPHFP à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que le FIPHFP ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que le FIPHFP ?","Question : qu'est-ce que le fiphfp ?","Pourriez-vous me donner une définition de le FIPHFP ?"]},{"id":"FRANCE-TRAVAIL-DEFINITION","question":"Comment France Travail accompagne-t-il les personnes handicapées ?","reponse":"France Travail (ex-Pôle emploi) accompagne les demandeurs d'emploi handicapés en partenariat avec Cap emploi : inscription, indemnisation, accompagnement personnalisé, formations, aides à l'embauche (dont l'OETH), accès à l'emploi accompagné. L'inscription est obligatoire pour percevoir l'AAH si vous avez une capacité de travail. France Travail travaille en réseau avec Cap emploi, l'Agefiph, les entreprises adaptées et les ESAT.","source":{"titre":"francetravail.fr","url":"https://www.francetravail.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["france travail","pole emploi","demandeur emploi handicap","inscription chomage","recherche emploi handicap","conseiller cap emploi","c'est quoi france travail","definition france travail","accompagnement handicap france travail","inscription france travail","aides recherche emploi france travail","Quel accompagnement France Travail propose-t-il aux demandeurs d'emploi handicapés ?","Je suis handicapé et au chômage, France Travail peut m'aider comment ?","Quel est le rôle de France Travail pour les travailleurs en situation de handicap ?","France Travail a-t-il des conseillers spécialisés dans le handicap ?","Quelle différence y a-t-il entre France Travail et Cap emploi pour quelqu'un qui a une RQTH ?","Comment l'ex-Pôle emploi aide-t-il les chercheurs d'emploi handicapés ?","Une personne avec une RQTH inscrite à France Travail bénéficie-t-elle d'un suivi particulier ?","Est-ce que France Travail peut financer une formation adaptée à mon handicap ?","France travail aide coment les handicapés ?","Quels services France Travail met-il à disposition des personnes en situation de handicap ?"]},{"id":"EMAS-DEFINITION","question":"Qu'est-ce que l'EMAS ?","reponse":"L'EMAS est une équipe pluridisciplinaire (enseignants spécialisés, psychologues, ergothérapeutes...) qui intervient, à la demande d'un établissement scolaire, pour appuyer les enseignants accueillant des élèves handicapés : adaptation des pratiques pédagogiques, stratégies d'enseignement, coordination avec l'AESH et l'équipe de suivi de scolarisation. Objectif : donner aux enseignants les moyens de répondre aux besoins de chaque élève.","source":{"titre":"education.gouv.fr","url":"https://www.education.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["emas","equipe mobile appui scolarisation","equipe mobile","aide scolarisation","soutien enseignants","accompagnement eleves handicap","c'est quoi emas","definition emas","role emas","mission emas","qui intervient emas","Pouvez-vous définir l'EMAS ?","À quoi correspond l'EMAS ?","Je cherche une explication sur l'EMAS : de quoi s'agit-il ?","C'est quoi l'EMAS ?","Vous pouvez m'expliquer l'EMAS ?","Comment présenter l'EMAS à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que l'EMAS ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que l'EMAS ?","Question : qu'est-ce que l'emas ?","Pourriez-vous me donner une définition de l'EMAS ?"]},{"id":"GOS-DEFINITION","question":"Qu'est-ce que le GOS ?","reponse":"Le GOS est une réunion de l'équipe pluridisciplinaire de la MDPH qui précède la CDAPH : elle examine les dossiers complexes, synthétise les évaluations, élabore un plan personnalisé de compensation et prépare les propositions de décision. Il regroupe médecins, travailleurs sociaux, ergothérapeutes, psychologues, parfois des partenaires extérieurs. Le GOS ne décide pas : il prépare le travail de la CDAPH, seule habilitée à notifier les droits.","source":{"titre":"mdph.fr","url":"https://www.mdph.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["gos","groupe operationnel synthese","reunion gos","equipe pluridisciplinaire mdph","evaluation mdph","preparation cdaph","c'est quoi gos","definition gos","role gos","qui participe gos","avant cdaph gos","Pouvez-vous définir le GOS ?","À quoi correspond le GOS ?","Je cherche une explication sur le GOS : de quoi s'agit-il ?","C'est quoi le GOS ?","Vous pouvez m'expliquer le GOS ?","Comment présenter le GOS à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que le GOS ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que le GOS ?","Question : qu'est-ce que le gos ?","Pourriez-vous me donner une définition de le GOS ?"]},{"id":"NIA-DEFINITION","question":"Qu'est-ce que le NIA (numéro de dossier MDPH) ?","reponse":"Le NIA est le numéro unique et anonyme attribué par la MDPH à chaque personne dès son premier dossier, conservé pour tous ses dossiers ultérieurs. Il sert à suivre l'avancement du dossier (portail en ligne, téléphone) et de référence pour toute correspondance. On le trouve sur l'accusé de réception du dépôt, les notifications de décision, ou le portail MDPH. En cas de perte, la MDPH peut le communiquer après vérification d'identité.","source":{"titre":"mdph.fr","url":"https://www.mdph.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["nia","numero identifiant anonyme","numero dossier mdph","identifiant mdph","numero unique mdph","reference dossier","c'est quoi nia","definition nia","ou trouver nia","a quoi sert nia","numero dossier nia","À quoi correspond le NIA figurant sur les courriers de la MDPH ?","C'est quoi le NIA ?","Le NIA, c'est mon numéro à la MDPH ?","Où trouver mon identifiant NIA de la MDPH ?","Le NIA est-il le même que mon numéro de sécurité sociale ?","À quoi sert le numéro NIA dans un dossier MDPH ?","Que signifie le sigle NIA sur une notification MDPH ?","Ma mère a un NIA, à quoi lui sert-il ?","Cest quoi le numero NIA ?","Est-ce que je dois indiquer mon NIA quand j'écris à la MDPH ?"]},{"id":"SDO-DEFINITION","question":"Qu'est-ce que le SDO ?","reponse":"Le SDO accompagne les personnes handicapées dans leur parcours d'orientation scolaire et professionnelle, en lien avec la MDPH : évaluation des compétences, information sur les formations, accès aux stages, mise en réseau avec l'Éducation nationale, les missions locales, Cap emploi et France Travail. Il travaille avec l'équipe pluridisciplinaire de la MDPH pour proposer des orientations qui seront validées par la CDAPH.","source":{"titre":"mdph.fr","url":"https://www.mdph.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["sdo","service departemental orientation","orientation mdph","orientation professionnelle handicap","orientation scolaire handicap","c'est quoi sdo","definition sdo","role sdo","mission sdo","orientation sdo","Pouvez-vous définir le SDO ?","À quoi correspond le SDO ?","Je cherche une explication sur le SDO : de quoi s'agit-il ?","C'est quoi le SDO ?","Vous pouvez m'expliquer le SDO ?","Comment présenter le SDO à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que le SDO ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que le SDO ?","Question : qu'est-ce que le sdo ?","Pourriez-vous me donner une définition de le SDO ?"]},{"id":"RAPT-DEFINITION","question":"Qu'est-ce que le RAPT, après un RAPO ?","reponse":"Le RAPT est l'étape de recours contentieux devant un tribunal, qui suit un RAPO rejeté ou resté sans réponse 2 mois : vous disposez alors de 2 mois pour saisir le tribunal compétent (tribunal judiciaire pour AAH/PCH/AEEH/CMI priorité ou invalidité ; tribunal administratif pour la CMI stationnement), en joignant la décision contestée, la réponse au RAPO et vos justificatifs. Un avocat n'est pas obligatoire ; comptez 6 à 20 mois de procédure.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["rapt","recours administratif prealable tribunal","recours tribunal mdph","contentieux mdph","saisir tribunal","c'est quoi rapt","definition rapt","apres rapo rapt","delai tribunal rapt","procedure rapt","À quoi correspond le RAPT qui intervient à la suite d'un RAPO ?","C'est quoi le RAPT ?","Le RAPT, ça vient après le RAPO ?","Que signifie le sigle RAPT dans un recours MDPH ?","Le RAPT est-il l'étape qui suit le rejet du RAPO ?","Quand le RAPO est rejeté, que représente le RAPT ?","Pouvez-vous m'expliquer ce qu'est un RAPT ?","Une personne dont le RAPO a échoué doit-elle passer par un RAPT ?","Cest quoi un RAPT aprés le RAPO ?","Est-ce que le RAPT est un recours devant le tribunal ?"]},{"id":"RSDAE-DEFINITION","question":"Qu'est-ce que la RSDAE pour un employeur ?","reponse":"La RSDAE (ex-RLH) est une aide versée à l'employeur pour compenser les surcoûts importants liés à l'emploi d'un salarié RQTH dont le handicap réduit la productivité ou nécessite des aménagements coûteux, afin de favoriser son maintien dans l'emploi. Demandée par l'employeur avec l'accord du salarié, versée par l'Agefiph (privé) ou le FIPHFP (public), pour une durée généralement de 3 ans renouvelable.","source":{"titre":"agefiph.fr","url":"https://www.agefiph.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["rsdae","reconnaissance lourdeur handicap","majoration lourdeur","aide employeur handicap","compensation cout handicap","subvention agefiph","c'est quoi rsdae","definition rsdae","pour employeur rsdae","montant aide rsdae","comment obtenir rsdae","Que signifie la restriction substantielle et durable pour l'accès à l'emploi du point de vue de l'entreprise ?","C'est quoi la RSDAE quand on est patron ?","La RSDAE, ça concerne l'employeur ?","Quel est l'impact de la RSDAE pour une entreprise qui emploie la personne ?","Un employeur doit-il tenir compte de la RSDAE d'un salarié ?","Que veut dire RSDAE côté employeur ?","Pour une entreprise, qu'implique la RSDAE d'un de ses salariés ?","Est-ce que la RSDAE change quelque chose pour mon employeur ?","Cest quoi la RSDEA pour une entreprise ?","Pouvez-vous définir la RSDAE et son intérêt pour un recruteur ?"]},{"id":"SLD-DEFINITION","question":"Qu'est-ce qu'une unité de soins de longue durée (USLD/SLD) ?","reponse":"Les USLD/SLD sont des unités hospitalières (contrairement aux EHPAD, structures médico-sociales) avec présence médicale 24h/24, pour des personnes âgées ou handicapées nécessitant une surveillance médicale constante et des soins lourds et continus. Les soins médicaux sont pris en charge par l'Assurance Maladie ; le forfait hospitalier et l'hébergement restent à charge du résident, avec une aide sociale départementale possible. Admission sur prescription médicale.","source":{"titre":"solidarites-sante.gouv.fr","url":"https://www.solidarites-sante.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["sld","soins longue duree","etablissement soins longue duree","hopital longue duree","hospitalisation longue duree","usld","c'est quoi sld","definition sld","pour qui sld","difference ehpad sld","admission sld","Que désigne une USLD ?","C'est quoi une unité de soins longue durée ?","Une USLD, ça accueille qui ?","Quel est le rôle d'un service de soins de longue durée à l'hôpital ?","Une USLD est-elle la même chose qu'un EHPAD ?","Qu'appelle-t-on SLD dans un hôpital ?","Ma grand-mère va être transférée en long séjour, qu'est-ce que c'est ?","Pouvez-vous m'expliquer ce qu'est une USLD ?","Cest quoi une USDL ?","Est-ce qu'un service de long séjour est un établissement médicalisé ?"]},{"id":"HANDICAP-MOTEUR-DROITS","question":"Quels droits pour une personne avec un handicap moteur ?","reponse":"Pour un handicap moteur (paraplégie, tétraplégie, difficultés de déplacement) : AAH (taux ≥80%, ou 50-79% avec restriction d'accès à l'emploi) ; PCH pour l'aide humaine, le fauteuil roulant, l'aménagement du logement et du véhicule ; CMI invalidité ou stationnement selon le taux ; RQTH pour l'emploi ; priorité au logement social. Pour un enfant : AEEH et PPS avec AESH. Demandes à la MDPH via le Cerfa 15692*01.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["handicap moteur","paraplegique","tetraplegique","fauteuil roulant","mobilite reduite","ampute","amputation","paralysie","marcher","deplacement difficile","handicap physique","difficulte marche","manque bras","manque jambe","prothese","Quelles aides et prestations sont accessibles en cas de handicap moteur ?","Je suis en fauteuil roulant, j'ai droit à quoi ?","Quels sont les droits des personnes à mobilité réduite ?","Un handicap moteur ouvre-t-il droit à la PCH et à la carte de stationnement ?","Que peut obtenir de la MDPH quelqu'un qui a des difficultés à se déplacer ?","Quelles aides existe-t-il quand on est paraplégique ?","Mon frère est atteint d'un handicap moteur, quelles prestations peut-il demander ?","Est-ce qu'avoir un handicap moteur donne droit à l'aménagement de mon logement ?","Jai quels droits si je suis handicapé moteur ?","Quels droits la loi reconnaît-elle aux personnes atteintes d'une déficience motrice ?","Je me déplace avec un déambulateur depuis mon AVC, quelles démarches puis-je faire ?","Mon enfant est né avec une infirmité motrice cérébrale, à quelles aides peut-il prétendre ?","J'ai perdu l'usage de mes jambes, quelles compensations existent ?"]},{"id":"HANDICAP-VISUEL-DROITS","question":"Quels droits pour une personne avec un handicap visuel ?","reponse":"Pour un handicap visuel (malvoyance, cécité) : AAH si taux ≥80% ; PCH pour l'accompagnement, les aides techniques (canne électronique, plage braille, synthèse vocale) et l'aménagement du logement ; CMI invalidité mention cécité (priorité, réductions transports, gratuité accompagnant SNCF) ; RQTH pour les aménagements de poste ; AEEH et PPS avec AESH spécialisé pour un enfant. Demandes à la MDPH.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["handicap visuel","malvoyant","aveugle","cecite","deficient visuel","vue","voir","vision","yeux","canne blanche","perds la vue","perdre la vue","dmla","perte vision progressive","quels droits handicap visuel","Quelles aides et prestations sont prévues en cas de déficience visuelle ?","Je suis malvoyant, j'ai droit à quoi ?","Quels sont les droits des personnes aveugles ou malvoyantes ?","La cécité donne-t-elle droit à la PCH ?","Que peut obtenir de la MDPH quelqu'un qui a une très mauvaise vue ?","Quelles aides existe-t-il quand on est non-voyant ?","Ma mère perd la vue, quelles prestations peut-elle demander ?","Est-ce qu'un handicap visuel permet d'avoir un chien guide financé ?","Quels sont les droits pour les malvoyents ?","Quels droits la réglementation accorde-t-elle aux personnes déficientes visuelles ?"]},{"id":"HANDICAP-AUDITIF-DROITS","question":"Quels droits pour une personne avec un handicap auditif ?","reponse":"Pour un handicap auditif (surdité, malentendance) : AAH selon le taux ; PCH pour l'interprétation en langue des signes, le codage LPC et les appareils auditifs ; RQTH avec aménagements (boucle magnétique, interprète LSF pris en charge par l'Agefiph/FIPHFP) ; CMI invalidité si taux ≥80% ; pour un enfant, AEEH et PPS avec interface de communication, orientation possible en ULIS. Certificat médical ORL détaillé requis.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["handicap auditif","sourd","malentendant","surdite","deficient auditif","entendre","audition","appareil auditif","langue signes","quels droits handicap auditif","quelles aides handicap auditif","ai-je droit handicap auditif","pretendre droits handicap auditif","beneficier handicap auditif","De quelles aides peut bénéficier quelqu'un qui souffre de déficience auditive ?","Je suis malentendant, j'ai droit à quoi ?","Quels sont les droits des personnes sourdes ou malentendantes ?","Un handicap auditif donne-t-il droit à la PCH ?","Que peut faire la MDPH pour quelqu'un qui entend mal ?","Quelles aides existe-t-il pour financer des appareils auditifs ?","Mon père devient sourd, quelles prestations peut-il demander ?","Est-ce qu'un handicap auditif permet d'avoir un interprète en langue des signes pris en charge ?","Jai droit a quoi si je suis malentendant ?","Quelles dispositions légales protègent les personnes sourdes ?","Ma fille est malentendante, quels soutiens existent pour l'école et le quotidien ?"]},{"id":"HANDICAP-INTELLECTUEL-DROITS","question":"Quels droits pour une personne avec un handicap intellectuel ?","reponse":"Pour un handicap intellectuel : AAH quasi systématique si taux ≥80% ; PCH pour l'accompagnement et la sécurisation du logement ; mesure de protection juridique possible (tutelle, curatelle) ; pour les enfants, AEEH, PPS avec AESH, orientation ULIS, IME ou SESSAD ; pour l'emploi, RQTH, ESAT, entreprise adaptée ou emploi accompagné ; hébergement en foyer de vie, FAM ou MAS selon le degré d'autonomie.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["handicap intellectuel","deficience intellectuelle","retard mental","handicap mental","trisomie","difficulte comprehension","autonomie reduite","apprentissage difficile","quels droits handicap intellectuel","quelles aides handicap intellectuel","ai-je droit handicap intellectuel","pretendre droits handicap intellectuel","beneficier handicap intellectuel","Quelles prestations sont ouvertes aux personnes atteintes de déficience intellectuelle ?","Mon fils a un retard mental, il a droit à quoi ?","Quels sont les droits des adultes ayant une déficience intellectuelle ?","Un handicap intellectuel ouvre-t-il droit à l'AAH ?","Que peut obtenir de la MDPH un adulte avec une déficience mentale ?","Quelles mesures de protection existe-t-il pour un adulte handicapé mental ?","Ma sœur est trisomique, quelles prestations peut-elle demander ?","Est-ce qu'une personne déficiente intellectuelle peut travailler en milieu ordinaire ?","Ma fille a un handicap mantal, elle a droit a quoi ?","Que prévoit la loi pour protéger les droits des personnes handicapées intellectuelles ?"]},{"id":"HANDICAP-PSYCHIQUE-DROITS","question":"Quels droits pour une personne avec un handicap psychique ?","reponse":"Pour un handicap psychique (trouble psychiatrique, dépression sévère, bipolarité) : AAH si taux ≥80% ou 50-79% avec restriction d'accès à l'emploi (fréquent dans ce cas) ; PCH pour l'accompagnement ; pension d'invalidité si activité antérieure ; RQTH avec aménagements (télétravail, mi-temps thérapeutique) ; accès aux SAVS/SAMSAH spécialisés, groupes d'entraide mutuelle. Un certificat médical psychiatre détaillé est essentiel pour l'évaluation MDPH.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["handicap psychique","maladie mentale","trouble psychiatrique","depression severe","bipolarite","schizophrenie","depression","probleme psychologique","suivi psychiatrique","hospitalisation psy","souffre depression","ne peux plus travailler","arret longue duree","burnout","epuisement professionnel","En cas de handicap psychique, quelles aides peut-on demander ?","J'ai une maladie psy, j'ai droit à quoi ?","Quels droits ont les personnes souffrant de troubles psychiques ?","Un handicap psychique est-il reconnu par la MDPH ?","Que peut obtenir de la MDPH quelqu'un qui a une schizophrénie ?","Quels accompagnements existe-t-il pour un adulte avec des troubles bipolaires ?","Mon fils est suivi en psychiatrie, quelles prestations peut-il demander ?","Est-ce qu'un trouble psychique permet d'avoir la RQTH ?","Les troubles pyschiques, ça donne droit a quoi ?","Quels droits la loi reconnaît-elle aux personnes en situation de handicap psychique ?"]},{"id":"DROITS-HANDICAP-GENERAL","question":"Quels sont les droits d'une personne en situation de handicap ?","reponse":"Les principaux droits selon la situation : AAH (revenu minimum, taux ≥80% ou 50-79% avec restriction d'emploi) ; PCH (aide humaine, technique, logement, véhicule) ; AEEH pour un enfant, complétée par la PCH ou l'AJPP ; CMI pour la mobilité et des avantages fiscaux ; RQTH, ESAT ou entreprise adaptée pour le travail ; PPS et AESH pour la scolarité ; priorité au logement social. Toutes les demandes se font à la MDPH avec le Cerfa 15692*01.","source":{"titre":"monparcourshandicap.gouv.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["quels droits handicap","quelles aides handicap","ai-je droit handicape","droits personne handicapee","beneficier handicap","pretendre droits","aides disponibles","liste aides handicap","handicape quels droits handicap","handicap quels droits handicap","reconnaissance handicap quels droits handicap","situation handicap quels droits handicap","je viens d'être reconnu handicapé quelles aides","on vient de me reconnaître handicapé et après","De quels droits bénéficient les personnes handicapées en France ?","Quand on est handicapé, on a droit à quoi ?","Quelles aides existent pour les personnes handicapées ?","La reconnaissance du handicap ouvre-t-elle des droits particuliers ?","Que peut-on demander à la MDPH quand on a un handicap ?","Quelles prestations la MDPH peut-elle attribuer ?","Mon cousin vient d'être reconnu handicapé, à quoi peut-il prétendre ?","Est-ce qu'il existe une liste des droits pour les handicapés ?","Les handicapés ont droit a quoi en France ?","Quel est l'ensemble des droits reconnus aux personnes handicapées par la loi de 2005 ?"]},{"id":"AMENAGEMENTS-ETUDES-SUPERIEURES","question":"Quels aménagements pour un étudiant handicapé dans le supérieur ?","reponse":"Les étudiants handicapés peuvent obtenir des aménagements pour leurs examens : temps majoré (tiers-temps ou plus), aides matérielles ou humaines, adaptation des supports ou du lieu. La demande se fait dès l'arrivée auprès de la Mission Handicap de l'établissement, avant la date limite d'inscription. Depuis 2022, les aménagements du bac se renouvellent automatiquement pour les concours et s'appliquent sur tout le cycle d'études. Ils n'apparaissent jamais sur le diplôme.","source":{"titre":"enseignementsup-recherche.gouv.fr, monparcourshandicap.gouv.fr","url":"https://www.enseignementsup-recherche.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["amenagements etudes superieures","amenagements universite","tiers temps universite","tiers temps etudes","amenagements examens universite","etudes medecine handicap","etudiant handicape","amenager mes etudes","amenager stages","malaises etudes","aides etudiants handicapes","aide financiere etudiant handicape","je suis etudiant amenagements etudes superieures","a l'universite amenagements etudes superieures","a la fac amenagements etudes superieures","Quelles adaptations sont possibles à l'université pour les étudiants handicapés ?","Je suis en fac avec un handicap, je peux avoir quoi comme aménagements ?","Comment obtenir un tiers-temps aux examens à l'université ?","Les écoles supérieures doivent-elles aménager les cours pour les élèves handicapés ?","Quel est le rôle de la mission handicap d'une université ?","Un étudiant en BTS avec une RQTH peut-il bénéficier d'aménagements ?","Ma fille entre à la fac et elle est dyslexique, quels aménagements peut-elle demander ?","Est-ce qu'on peut avoir un preneur de notes à l'université quand on est handicapé ?","Il existe quels aménagment à la fac pour les handicapés ?","Quelles mesures d'accompagnement les établissements d'enseignement supérieur proposent-ils aux étudiants handicapés ?","J'ai une RQTH et je commence un master, à qui m'adresser pour adapter mes études ?"]},{"id":"MALADIES-CHRONIQUES-HANDICAP","question":"Une maladie chronique peut-elle être reconnue comme un handicap ?","reponse":"Une maladie chronique invalidante (diabète, Crohn, apnée du sommeil...) peut être reconnue par la MDPH si le taux d'incapacité dépasse 50% et que la maladie est déséquilibrée ou invalidante, attesté par un spécialiste. Cela ouvre droit à la RQTH, l'AAH (si taux ≥50% avec difficultés durables d'accès à l'emploi) et la PCH. Par ailleurs, ces maladies sont prises en charge à 100% par la Sécurité sociale au titre d'une Affection Longue Durée.","source":{"titre":"dossier-mdph.fr, service-public.fr, ameli.fr","url":"https://www.dossier-mdph.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["diabete handicap","maladie chronique handicap","diabete type 1","diabete type 2","maladie de crohn","apnee du sommeil","diabete complications","maladie chronique mdph","stomie","diabete desequilibre","complications visuelles diabete","fatigue chronique","maladie invalidante","je suis diabetique diabete handicap","j'ai le diabete diabete handicap","La MDPH prend-elle en compte les pathologies chroniques ?","J'ai du diabète, est-ce que c'est considéré comme handicap ?","Peut-on être reconnu handicapé avec une maladie chronique ?","Une sclérose en plaques ouvre-t-elle des droits auprès de la MDPH ?","Les maladies chroniques donnent-elles droit à une reconnaissance de handicap ?","Quelqu'un atteint de la maladie de Crohn peut-il demander l'AAH ?","Une ALD est-elle automatiquement un handicap ?","Est-ce qu'on peut faire un dossier MDPH pour une maladie qui dure depuis longtemps ?","Une maladie cronique c'est un handicap ?","Dans quelle mesure une pathologie au long cours est-elle assimilée à un handicap ?","Quels critères la MDPH applique-t-elle pour reconnaître un handicap en cas de maladie de longue durée ?"]},{"id":"PROTECTION-DISCRIMINATION-HANDICAP","question":"Comment se protéger contre une discrimination liée au handicap ?","reponse":"Le handicap est le premier motif de discrimination en France. La loi interdit toute discrimination liée au handicap, y compris le refus d'aménagement raisonnable, au travail, dans l'éducation et l'accès aux services. Recours : le Défenseur des droits (gratuit, 39 28, antidiscriminations.fr) examine la situation et peut accompagner la personne ; pour le travail, saisine possible du conseil de prud'hommes ; un recours pénal est possible devant le tribunal correctionnel.","source":{"titre":"defenseurdesdroits.fr, travail-emploi.gouv.fr","url":"https://www.defenseurdesdroits.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["discrimination handicap","proteger contre discrimination","recours discrimination","discrimination travail","discrimination embauche","defenseur des droits","victime discrimination","plainte discrimination","harcelement handicap","je subis discrimination handicap","je suis victime discrimination handicap","comment me proteger discrimination handicap","mes droits discrimination handicap","porter plainte discrimination handicap","Quels recours existent quand on est discriminé en raison de son handicap ?","Mon patron me traite mal à cause de mon handicap, je fais quoi ?","Que faire face à une discrimination parce qu'on est handicapé ?","Le Défenseur des droits peut-il intervenir en cas de discrimination envers une personne handicapée ?","Comment prouver qu'on a été traité injustement à cause de son handicap ?","Un salarié handicapé écarté d'une promotion peut-il porter plainte ?","Quelles lois protègent les personnes handicapées des discriminations ?","Est-ce que refuser un logement à une personne handicapée est puni par la loi ?","On ma refusé un emploi à cause de mon handicap, c'est légal ?","Comment faire valoir ses droits face à un traitement inégal dû au handicap ?","On m'a refusé l'entrée dans un restaurant avec mon chien guide, que puis-je faire ?"]},{"id":"HANDICAP-AUDITIF-IMPLANT","question":"Quels droits avec un implant cochléaire ou une surdité ?","reponse":"La surdité totale donne automatiquement un taux d'incapacité de 80% (audiogramme réalisé sans appareillage). Elle ouvre droit à l'AAH, la RQTH, la CMI et à la PCH, avec un forfait spécifique : jusqu'à 30h/mois d'aide humaine pour la communication si la perte auditive dépasse 70 dB, et prise en charge à 75% (jusqu'à 6000€ sur 10 ans) du matériel et de l'implant. Dossier MDPH avec audiogramme sans appareillage de moins de 6 mois.","source":{"titre":"monparcourshandicap.gouv.fr, cisic.fr, surdifrance.org","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["handicap auditif","surdite","implant cochleaire","sourd","sourde","malentendant","appareil auditif","prothese auditive","perte auditive","deficience auditive","interprete lsf","langue des signes","je suis sourd handicap auditif","je suis sourde handicap auditif","je n'entends pas handicap auditif","Quelles aides sont prévues pour les personnes porteuses d'un implant cochléaire ?","J'ai un implant cochléaire, j'ai droit à quoi ?","Être implanté cochléaire donne-t-il droit à la PCH ?","Quels droits ouvre une surdité profonde ?","Le remplacement du processeur de l'implant cochléaire peut-il être financé ?","Un enfant sourd implanté peut-il bénéficier de l'AEEH ?","Ma fille porte un implant cochléaire, quelles prestations peut-elle demander ?","Est-ce qu'un implant cochléaire permet d'obtenir la RQTH ?","On a droit a quoi quand on est implanté cochléaire ?","Quelles prestations la MDPH accorde-t-elle en cas de surdité sévère ou profonde ?"]},{"id":"SCOLARISATION-HOSPITALISATIONS-FREQUENTES","question":"Comment continuer la scolarité en cas d'hospitalisations fréquentes ?","reponse":"Un élève dont la scolarité est interrompue pour raisons médicales peut bénéficier d'un accompagnement pédagogique : l'APADHE (gratuit, dès 2 semaines d'interruption, enseignants de l'Éducation nationale à domicile ou à l'hôpital), le SAPAD (dispositif départemental), des classes dans les établissements hospitaliers, ou le CNED (gratuit jusqu'à 16 ans sur validation médicale, gratuit au-delà si handicap reconnu). Démarche : contacter l'établissement scolaire ou l'Inspecteur académique avec un certificat médical.","source":{"titre":"education.gouv.fr, eduscol.education.fr","url":"https://www.education.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["scolarisation hospitalisations","ecole hopital","hospitalisation scolarite","continuer scolarite hospitalisation","sapad","apadhe","cned","ecole a domicile","cours hopital","eleve malade","absence scolaire maladie","est hospitalise scolarisation hospitalisations","hospitalisations frequentes scolarisation hospitalisations","souvent a l'hopital scolarisation hospitalisations","absent pour maladie scolarisation hospitalisations","Quelles solutions existent pour qu'un élève souvent hospitalisé poursuive ses études ?","Mon fils est tout le temps à l'hôpital, comment il fait pour l'école ?","Comment fonctionne l'école à l'hôpital pour les enfants malades ?","Un enfant hospitalisé régulièrement peut-il avoir des cours à domicile ?","Qu'est-ce que le SAPAD et comment en bénéficier ?","Quelle organisation scolaire prévoir pour une élève qui enchaîne les séjours à l'hôpital ?","Ma fille a de nombreuses hospitalisations, comment éviter qu'elle décroche à l'école ?","Est-ce que l'Éducation nationale propose des cours pour les élèves absents pour raisons médicales ?","Comment suivre les cours quand on est souvant hospitalisé ?","De quels dispositifs dispose un collégien gravement malade pour ne pas perdre son année ?"]},{"id":"HANDICAP-PERMIS-CONDUIRE","question":"Quelles règles pour le permis de conduire en cas de handicap ou pathologie ?","reponse":"Toute pathologie pouvant affecter la conduite (apnée du sommeil, épilepsie, diabète, troubles visuels...) impose de consulter un médecin agréé par la préfecture, pas son médecin traitant : il évalue l'aptitude, pour maximum 3 ans, avec possibilité d'aménagements du véhicule. Sans cet avis, un accident lié à la pathologie n'est pas couvert par l'assurance. La visite est gratuite si le taux d'incapacité reconnu est d'au moins 50%.","source":{"titre":"service-public.fr, legifrance.gouv.fr","url":"https://www.service-public.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["permis conduire handicap","permis handicap","apnee sommeil permis","visite medicale permis","commission medicale permis","medecin agree permis","aptitude conduite","somnolence conduite","amenagement vehicule","conduite handicap","risque permis","conducteur permis conduire handicap","je conduis permis conduire handicap","permis de conduire permis conduire handicap","aptitude a conduire permis conduire handicap","Peut-on passer son permis de conduire quand on est handicapé ?","J'ai une maladie, est-ce que je peux garder mon permis ?","Faut-il passer une visite médicale pour conduire avec un handicap ?","Quelles conditions médicales s'appliquent à la conduite automobile ?","Un conducteur épileptique doit-il déclarer sa maladie à la préfecture ?","Comment obtenir un permis avec un véhicule aménagé ?","Mon père a eu un AVC, a-t-il encore le droit de conduire ?","Est-ce qu'il faut l'avis d'un médecin agréé pour conduire après un problème de santé ?","On peut conduire avec un handicape ?","Quelle réglementation encadre la conduite pour les personnes atteintes de certaines maladies ?"]},{"id":"INCAPACITE-TRAVAIL-HANDICAP-PSY","question":"Quelles aides si on ne peut plus travailler à cause d'un handicap ?","reponse":"Si un handicap empêche de travailler : l'arrêt maladie verse des indemnités journalières (possibilité d'ALD, prise en charge à 100%) ; après 3 ans maximum, une pension d'invalidité peut être examinée si la capacité de travail est réduite d'au moins 2/3 (catégorie 1 : capacité réduite, 2 : incapacité de travailler, 3 : avec besoin d'une tierce personne). L'AAH reste possible selon le taux ; si la pension est inférieure, une AAH différentielle complète jusqu'au montant maximal.","source":{"titre":"ameli.fr, securite-sociale.fr","url":"https://www.ameli.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["incapacite travail","ne peux plus travailler","arret travail longue duree","pension invalidite","arret maladie","indemnites journalieres","invalidite categorie","capacite travail reduite","ne peut pas travailler","trop malade pour travailler","impossible de travailler incapacite travail","arret depuis incapacite travail","capacite reduite incapacite travail","Quelles ressources existent quand on est dans l'incapacité de travailler du fait de son état ?","Je suis plus capable de bosser à cause de mon handicap, je touche quoi ?","Quelles prestations sont prévues pour une personne inapte au travail ?","L'AAH peut-elle être versée si je dois arrêter de travailler ?","Mes troubles psychiques m'empêchent de travailler, quelles aides puis-je demander ?","Un salarié déclaré inapte peut-il toucher une pension d'invalidité ?","Comment vivre financièrement quand le handicap empêche toute activité professionnelle ?","Est-ce qu'il existe une aide si je n'arrive plus à garder un emploi ?","Je suis inapte au travail, j'ai le droit a quelles aides ?","Quels revenus de remplacement sont prévus pour les personnes que leur handicap éloigne durablement de l'emploi ?"]},{"id":"AMENAGEMENTS-EXAMENS-SECONDAIRE","question":"Quels aménagements pour le brevet ou le bac en cas de handicap ?","reponse":"Les élèves handicapés peuvent obtenir des aménagements pour le brevet, le CAP, le bac ou le BTS : temps majoré (tiers-temps, soit +33%, exceptionnellement plus sur avis médical), aides techniques ou humaines, adaptation des supports ou du lieu. Une procédure simplifiée existe pour les élèves ayant déjà un PAI, PAP ou PPS ; les autres suivent une procédure complète. Depuis 2022, les aménagements du bac se renouvellent automatiquement pour les concours.","source":{"titre":"education.gouv.fr, onisep.fr","url":"https://www.education.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["amenagements examens bac","tiers temps bac","amenagements brevet","amenagements lycee","amenagements dnb","amenagements cap","amenagements bac pro","amenagements bts","temps supplementaire examens","aide examens handicap","pour le bac amenagements examens bac","pour le brevet amenagements examens bac","au lycee amenagements examens bac","au college amenagements examens bac","examens secondaire amenagements examens bac","Quelles adaptations peut-on obtenir aux examens du collège et du lycée quand on est handicapé ?","Mon fils est dyslexique, il peut avoir un tiers-temps au bac ?","Comment demander un tiers-temps pour le baccalauréat ?","Un élève handicapé peut-il avoir un secrétaire pour passer le brevet ?","Quelles sont les démarches pour obtenir des aménagements d'épreuves au DNB ?","Qui décide des aménagements d'examen pour un lycéen handicapé ?","Ma fille a un PAP, peut-elle bénéficier d'un aménagement au brevet des collèges ?","Est-ce qu'on peut utiliser un ordinateur pendant le bac quand on a un handicap ?","Comment avoir un tier temps au bac ?","Quels aménagements d'épreuves sont prévus pour les candidats handicapés aux examens nationaux ?"]},{"id":"PCH-AIDES-TECHNIQUES","question":"La PCH peut-elle financer du matériel (fauteuil, prothèse...) ?","reponse":"La PCH Aides Techniques finance le matériel compensant le handicap : les équipements remboursables par la Sécurité sociale (prothèses, fauteuils roulants) sont complétés par la PCH pour la part non remboursée ; d'autres équipements (sièges de bain, aides à la communication...) sont couverts selon une liste réglementaire. Prise en charge à 80 ou 100% selon les ressources, plafonnée à 3960€ sur 3 ans. Un devis est obligatoire, à demander avant tout achat.","source":{"titre":"monparcourshandicap.gouv.fr, informations.handicap.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["pch aides techniques","materiel medical pch","fauteuil roulant pch","aides equipement handicap","orthese","prothese","equipement adapte","materiel adapte","financement fauteuil","achat materiel handicap","appareil medical","acheter materiel pch aides techniques","financer equipement pch aides techniques","aide pour materiel pch aides techniques","payer fauteuil pch aides techniques","La prestation de compensation du handicap prend-elle en charge l'achat d'équipements adaptés ?","Je peux me faire rembourser mon fauteuil roulant par la PCH ?","Quelles aides techniques sont couvertes par la PCH ?","La PCH rembourse-t-elle une prothèse ou un appareil auditif ?","Comment obtenir un financement PCH pour un fauteuil électrique ?","Un bénéficiaire de la PCH peut-il s'en servir pour acheter un lit médicalisé ?","Quel montant la PCH aides techniques peut-elle couvrir ?","Est-ce que la PCH paie le matériel adapté non remboursé par la Sécu ?","La PCH peut payer un fauteil ?","Pour une aide technique, quelle part la PCH finance-t-elle après la Sécurité sociale ?"]},{"id":"AIDES-PARENTS-ENFANT-HANDICAPE","question":"Quelles aides financières pour les parents d'un enfant handicapé ?","reponse":"Pour un enfant handicapé : l'AEEH (sans condition de ressources) peut être complétée par un complément AEEH (6 catégories, selon l'aide humaine ou les dépenses nécessaires, 2 à 5 ans) ou par l'AJPP si un parent interrompt son activité (22 jours/mois maximum, 310 jours sur 3 ans). L'AEEH de base se cumule avec la PCH ou l'AJPP, mais le complément AEEH ne se cumule ni avec la PCH (sauf exceptions) ni avec l'AJPP.","source":{"titre":"monparcourshandicap.gouv.fr, caf.fr","url":"https://www.monparcourshandicap.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["aides parents enfant handicape","aeeh parents","complement aeeh","ajpp","allocation enfant handicape","aides financieres parents","aide education enfant handicape","majoration parent isole","allocation journaliere presence parentale","mon enfant handicape aides parents enfant handicape","parents aides parents enfant handicape","pour mon enfant aides parents enfant handicape","famille aides parents enfant handicape","aide financiere enfant aides parents enfant handicape","mon enfant vient d'être reconnu handicapé","Quelles prestations peuvent percevoir les familles ayant un enfant handicapé ?","Notre fille est handicapée, on peut toucher quoi comme aides ?","Quels soutiens financiers existent pour élever un enfant en situation de handicap ?","L'AEEH est-elle la seule aide pour les familles d'enfants handicapés ?","Comment financer la prise en charge de son enfant handicapé ?","Un parent qui réduit son activité pour s'occuper de son enfant handicapé est-il indemnisé ?","Quelles allocations la CAF verse-t-elle quand un enfant est reconnu handicapé ?","Est-ce qu'on peut être aidé financièrement si on arrête de travailler pour son enfant handicapé ?","On a droit a quelles aides avec un enfant handicapé ?","Quels dispositifs d'aide financière sont prévus pour les foyers élevant un enfant porteur de handicap ?"]},{"id":"SCOLARISATION-TROUBLES-COMPORTEMENT","question":"Quel accompagnement scolaire pour un enfant avec des troubles du comportement ?","reponse":"Pour un enfant avec des troubles du comportement (TDAH, troubles de l'opposition...) : un PAP permet des aménagements pédagogiques sans reconnaissance de handicap ; un PPS (via la MDPH) et une notification d'AESH sont possibles si le handicap est reconnu, avec orientation éventuelle en ULIS ou appui d'un SESSAD. En cas d'exclusions répétées, solliciter l'équipe éducative puis l'équipe de suivi de scolarisation pour évaluer les besoins.","source":{"titre":"education.gouv.fr, enfant-different.org","url":"https://www.education.gouv.fr/"},"verifie_le":"2026-11-23","proprietaire":"À valider par le comité métier (import chatbot-keywords-mdph, non relu)","revue_avant":"2026-12-23","reformulations":["scolarisation troubles comportement","tdah ecole","trouble opposition ecole","exclusions scolaires","enfant exclu ecole","troubles comportement scolarite","hyperactivite ecole","comportement inadapte classe","difficultes comportementales ecole","se fait exclure scolarisation troubles comportement","exclusions scolarisation troubles comportement","problemes comportement scolarisation troubles comportement","a l'ecole scolarisation troubles comportement","en classe scolarisation troubles comportement","Comment l'école peut-elle accompagner un élève qui présente des troubles du comportement ?","Mon fils est très agité en classe, quelles aides existent à l'école ?","Quels dispositifs scolaires sont prévus pour les élèves aux comportements difficiles ?","Un élève présentant des troubles du comportement peut-il avoir un AESH ?","À quoi sert un DITEP quand un élève a des difficultés de comportement ?","Quelle scolarité envisager pour une enfant qui a des troubles du comportement ?","Ma fille se met souvent en crise à l'école, quel soutien peut-elle recevoir ?","Est-ce que la MDPH peut orienter un enfant au comportement difficile vers un dispositif adapté ?","Mon fils a des troubles du comportment, comment l'aider à l'école ?","Quelles réponses éducatives propose l'Éducation nationale aux enfants présentant des troubles du comportement ?"]},{"id":"PCH-PARENTALITE-001","question":"Qu'est-ce que la PCH Parentalité ?","reponse":"La PCH Parentalité aide les parents en situation de handicap à exercer leur rôle parental. Elle compense les difficultés liées au handicap pour s'occuper d'un enfant, de sa naissance jusqu'à ses 6 ou 7 ans selon les cas. Elle comprend une aide humaine et, le cas échéant, une aide technique (matériel de puériculture adapté).","source":{"titre":"PCH Parentalité — Service-Public.fr","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F35575"},"verifie_le":"2026-11-23","proprietaire":"Jeu de test factice (non validé MDA)","revue_avant":"2027-05-23","reformulations":["c'est quoi la pch parentalité","pch parentalité définition","aide parentalité handicap","pch pour les parents handicapés","pch parentalité à qui s'adresse","pch parentalité conditions","aide pour parent handicapé avec bébé","pch parentalité jusqu'à quel âge de l'enfant","Pouvez-vous définir la PCH Parentalité ?","À quoi correspond la PCH Parentalité ?","Je cherche une explication sur la PCH Parentalité : de quoi s'agit-il ?","C'est quoi la PCH Parentalité ?","Vous pouvez m'expliquer la PCH Parentalité ?","Comment présenter la PCH Parentalité à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que la PCH Parentalité ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que la PCH Parentalité ?","Question : qu'est-ce que la pch parentalite ?","Pourriez-vous me donner une définition de la PCH Parentalité ?"]},{"id":"HEBERGEMENT-TEMP-001","question":"Comment fonctionne l'hébergement temporaire en établissement handicap ?","reponse":"L'hébergement temporaire permet à une personne en situation de handicap, quel que soit son âge, d'être accueillie dans un établissement pour une durée limitée, par exemple en cas de répit de l'aidant ou de période de transition. La demande se fait auprès de la MDPH, qui instruit le dossier comme une demande classique.","source":{"titre":"Hébergement temporaire — Service-Public.fr","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F10468"},"verifie_le":"2026-11-23","proprietaire":"Jeu de test factice (non validé MDA)","revue_avant":"2027-05-23","reformulations":["hébergement temporaire handicap","comment demander un hébergement temporaire","répit aidant hébergement","hébergement de courte durée handicap","accueil temporaire établissement handicap","solution de répit pour aidant","hébergement temporaire comment ça marche","qui demande l'hébergement temporaire","Quelles sont les règles de l'accueil temporaire dans une structure pour personnes handicapées ?","On peut placer mon fils quelques semaines en foyer pour souffler ?","Comment se passe un séjour temporaire en MAS ou en foyer ?","L'hébergement temporaire est-il limité à 90 jours par an ?","Qui finance l'accueil temporaire d'un adulte handicapé ?","Comment obtenir une place en hébergement temporaire ?","Une famille épuisée peut-elle confier son proche handicapé pour quelques jours de répit ?","Est-ce qu'il faut une orientation MDPH pour faire un accueil temporaire ?","Comment marche l'hébergement temporère ?","Quel est le principe de l'hébergement temporaire dans le secteur médico-social ?","Mon frère handicapé peut-il être accueilli en foyer pendant mon hospitalisation ?"]},{"id":"INVALIDITE-001","question":"Quelle est la différence entre invalidité et handicap ?","reponse":"Attention à ne pas confondre : l'invalidité (reconnue par la Sécurité sociale) concerne une personne qui, après une maladie ou un accident non professionnel, perd au moins 2/3 de sa capacité de travail ou de gain. Le handicap, lui, est évalué par la CDAPH de la MDPH sur un taux d'incapacité, selon des critères différents et indépendants.","source":{"titre":"Qu'est-ce que l'invalidité au sens de la sécurité sociale ? — Service-Public.fr","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F13093"},"verifie_le":"2026-11-23","proprietaire":"Jeu de test factice (non validé MDA)","revue_avant":"2027-05-23","reformulations":["différence invalidité handicap","invalidité et handicap c'est pareil","pension invalidité et mdph c'est lié","invalidité sécurité sociale définition","handicap et invalidité même chose","qui décide de l'invalidité","invalidité c'est la mdph ou la sécu","taux invalidité vs taux incapacité","En quoi l'invalidité se distingue-t-elle du handicap ?","Invalide et handicapé, c'est pareil ?","Comment distinguer une pension d'invalidité d'une reconnaissance de handicap ?","L'invalidité de la Sécu et le handicap reconnu par la MDPH sont-ils la même chose ?","Qu'est-ce qui sépare la notion d'invalidité de celle de handicap ?","Pourquoi parle-t-on tantôt d'invalidité, tantôt de handicap ?","Mon père est en invalidité, est-il pour autant reconnu handicapé ?","Est-ce que le taux d'invalidité et le taux d'incapacité veulent dire la même chose ?","Invalidité ou handicap, c'est quoi la diférence ?","Quelles différences y a-t-il entre le statut d'invalide et celui de personne handicapée ?"]},{"id":"FOYER-VIE-001","question":"Qu'est-ce qu'un foyer de vie ?","reponse":"Le foyer de vie (ou foyer occupationnel) accueille des personnes en situation de handicap qui ne peuvent pas exercer d'activité professionnelle, mais qui disposent d'une autonomie suffisante pour des activités occupationnelles et sociales. L'admission est décidée par la CDAPH sur dossier déposé à la MDPH.","source":{"titre":"Foyer de vie — Service-Public.fr","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F2005"},"verifie_le":"2026-11-23","proprietaire":"Jeu de test factice (non validé MDA)","revue_avant":"2027-05-23","reformulations":["c'est quoi un foyer de vie","foyer occupationnel définition","foyer de vie pour qui","admission foyer de vie","différence foyer de vie et fam","foyer occupationnel comment y entrer","foyer de vie activités","dossier pour un foyer de vie","Que désigne un foyer de vie pour adultes handicapés ?","C'est quoi un foyer de vie ?","Un foyer de vie, ça accueille qui ?","Quel est le rôle d'un foyer occupationnel ?","Le foyer de vie est-il la même chose qu'un FAM ?","Comment fonctionne un foyer de vie au quotidien ?","Mon frère va entrer en foyer de vie, en quoi ça consiste ?","Pouvez-vous m'expliquer ce qu'est un foyer de vie ?","Cest quoi un foyé de vie ?","Est-ce qu'en foyer de vie les résidents travaillent ?"]},{"id":"MAS-001","question":"Qu'est-ce qu'une MAS ?","reponse":"La maison d'accueil spécialisée (Mas) héberge des personnes en situation de handicap très dépendantes, nécessitant l'aide d'une tierce personne pour les actes de la vie courante. Elle propose un hébergement permanent, des soins médicaux et des activités de vie sociale, pour des personnes plus dépendantes qu'en foyer d'accueil médicalisé (Fam).","source":{"titre":"Maison d'accueil spécialisée (Mas) — Service-Public.fr","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F2006"},"verifie_le":"2026-11-23","proprietaire":"Jeu de test factice (non validé MDA)","revue_avant":"2027-05-23","reformulations":["c'est quoi une mas","mas définition handicap","maison accueil spécialisée c'est quoi","différence mas et fam","mas pour qui","mas plus dépendant que fam","admission en mas","dossier mas démarche","Que désigne une maison d'accueil spécialisée ?","C'est quoi une MAS ?","Une MAS, ça accueille quel genre de personnes ?","Quel est le rôle d'une maison d'accueil spécialisée ?","Une MAS est-elle un établissement médicalisé ?","Comment fonctionne une MAS pour les adultes polyhandicapés ?","Ma cousine va être accueillie en MAS, qu'est-ce que ça veut dire ?","Pouvez-vous m'expliquer ce qu'est une MAS ?","Cest quoi une maison d'acceuil spécialisée ?","Est-ce que la MAS est financée par l'Assurance maladie ?","La MDPH propose une orientation en MAS pour mon fils, c'est quoi comme structure ?"]},{"id":"FAM-001","question":"Qu'est-ce qu'un FAM ?","reponse":"Le foyer d'accueil médicalisé (Fam) héberge des personnes en situation de handicap dépendantes, nécessitant l'aide d'une tierce personne pour les actes de la vie courante. Il propose un hébergement permanent, des soins médicaux et des activités de vie sociale, pour des personnes moins dépendantes qu'en maison d'accueil spécialisée (Mas).","source":{"titre":"Foyer d'accueil médicalisé (Fam) — Service-Public.fr","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F15255"},"verifie_le":"2026-11-23","proprietaire":"Jeu de test factice (non validé MDA)","revue_avant":"2027-05-23","reformulations":["c'est quoi un fam","fam définition handicap","foyer accueil médicalisé c'est quoi","différence fam et mas","fam pour qui","fam moins dépendant que mas","admission en fam","dossier fam démarche","Que désigne un foyer d'accueil médicalisé ?","C'est quoi un FAM ?","Un FAM, ça accueille qui ?","Quel est le rôle d'un foyer d'accueil médicalisé ?","Le FAM est-il réservé aux adultes ?","Comment fonctionne un FAM au quotidien ?","Mon oncle va entrer en FAM, de quoi s'agit-il ?","Pouvez-vous m'expliquer ce qu'est un FAM ?","Cest koi un FAM ?","Est-ce qu'un FAM est financé par le département ?","La CDAPH a orienté mon frère vers un FAM, qu'est-ce que c'est ?"]},{"id":"SCOLARISATION-001","question":"Comment inscrire un enfant handicapé à l'école primaire ?","reponse":"La scolarisation d'un enfant en situation de handicap en école primaire se fait en milieu ordinaire chaque fois que possible. L'inscription suit la procédure habituelle auprès de la mairie ou de l'établissement, en lien avec l'équipe pluridisciplinaire de la MDPH qui évalue les besoins et peut proposer un accompagnement ou des aménagements.","source":{"titre":"Scolarisation en école primaire — Service-Public.fr","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F14984"},"verifie_le":"2026-11-23","proprietaire":"Jeu de test factice (non validé MDA)","revue_avant":"2027-05-23","reformulations":["inscription école enfant handicapé","scolarisation enfant handicap primaire","comment inscrire mon enfant handicapé à l'école","école et mdph enfant handicapé","scolarisation maternelle enfant handicapé","école élémentaire et handicap démarche","mon enfant handicapé rentre en primaire","à quel âge inscrire un enfant handicapé à l'école","Quelles démarches suivre pour scolariser un élève handicapé en primaire ?","Mon fils est handicapé, comment je fais pour l'inscrire à l'école ?","Comment se passe l'inscription en maternelle d'un enfant en situation de handicap ?","Mon enfant handicapé peut-il être inscrit dans l'école de son quartier ?","Faut-il passer par la MDPH pour scolariser son enfant handicapé au CP ?","Quel est le rôle de la mairie dans l'inscription scolaire d'un élève handicapé ?","Ma fille autiste a 3 ans, comment l'inscrire en maternelle ?","Est-ce que l'école peut refuser d'inscrire mon enfant à cause de son handicap ?","Comment inscrir mon enfant handicaper en primaire ?","Quelles étapes faut-il respecter pour la scolarisation en élémentaire d'un enfant porteur de handicap ?"]},{"id":"EMPLOI-ACCOMPAGNE-001","question":"Qu'est-ce que l'emploi accompagné ?","reponse":"Le dispositif d'emploi accompagné s'adresse aux personnes en situation de handicap qui recherchent un emploi en milieu ordinaire ou qui rencontrent des difficultés pour s'y maintenir. Il associe un accompagnement médico-social et un appui à l'insertion professionnelle, assuré conjointement par un organisme spécialisé et, si besoin, par le service public de l'emploi.","source":{"titre":"Emploi accompagné — Service-Public.fr","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F34063"},"verifie_le":"2026-11-23","proprietaire":"Jeu de test factice (non validé MDA)","revue_avant":"2027-05-23","reformulations":["c'est quoi l'emploi accompagné","dispositif emploi accompagné handicap","emploi accompagné définition","comment bénéficier de l'emploi accompagné","emploi accompagné pour qui","aide pour garder son emploi handicap","qui accompagne vers l'emploi en situation de handicap","emploi accompagné et pôle emploi","Pouvez-vous définir l'emploi accompagné ?","À quoi correspond l'emploi accompagné ?","Je cherche une explication sur l'emploi accompagné : de quoi s'agit-il ?","C'est quoi l'emploi accompagné ?","Vous pouvez m'expliquer l'emploi accompagné ?","Comment présenter l'emploi accompagné à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que l'emploi accompagné ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que l'emploi accompagné ?","Question : qu'est-ce que l'emploi accompagne ?","Pourriez-vous me donner une définition de l'emploi accompagné ?"]},{"id":"DEMENAGEMENT-001","question":"Quelles aides en cas de déménagement ?","reponse":"Un déménagement peut ouvrir droit à plusieurs aides financières : aide au logement (APL, ALS ou ALF), aide au dépôt de garantie, aide aux frais d'installation. Les conditions et montants varient selon votre statut (locataire, colocataire, propriétaire). Ces aides sont indépendantes des prestations liées au handicap (PCH, AAH).","source":{"titre":"Vous déménagez : aides financières — Service-Public.fr","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F38492"},"verifie_le":"2026-11-23","proprietaire":"Jeu de test factice (non validé MDA)","revue_avant":"2027-05-23","reformulations":["aides financières déménagement","déménagement et handicap aides","aide dépôt de garantie déménagement","quelles aides pour déménager","aide frais d'installation nouveau logement","apl als alf différence déménagement","aide au déménagement locataire propriétaire","déménagement et 3e enfant aide","Quelles aides peut-on obtenir lorsqu'on change de logement en situation de handicap ?","Je déménage, est-ce que j'ai droit à une aide ?","Que deviennent mes droits MDPH si je déménage dans un autre département ?","Le déménagement d'une personne handicapée peut-il être financé ?","Comment transférer son dossier MDPH après un déménagement ?","La PCH peut-elle aider à payer les frais de déménagement ?","Une personne handicapée qui change de département garde-t-elle son AAH ?","Est-ce qu'il faut refaire une demande à la MDPH quand on déménage ?","Je démenage, quelles aides je peux avoir ?","Quels soutiens existent pour l'installation dans un nouveau logement d'une personne handicapée ?","Je déménage dans une autre région, mes allocations vont-elles suivre ?","Je change de MDPH en cours d'instruction, comment ça se passe ?","Mes notifications restent-elles valables si je m'installe ailleurs ?"]},{"id":"ACCUEIL-FAMILIAL-001","question":"Qu'est-ce que l'accueil familial ?","reponse":"L'accueil familial permet à une personne âgée ou en situation de handicap d'être hébergée au domicile d'un accueillant familial agréé, de façon temporaire ou définitive. La personne accueillie rémunère l'accueillant familial et peut percevoir des aides financières sous conditions (APA, PCH, aide sociale à l'hébergement) pour couvrir ce coût.","source":{"titre":"Accueil familial — Service-Public.fr","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F15240"},"verifie_le":"2026-11-23","proprietaire":"Jeu de test factice (non validé MDA)","revue_avant":"2027-05-23","reformulations":["c'est quoi l'accueil familial","accueillant familial définition","accueil familial handicap","comment devenir accueillant familial","accueil familial rémunération","différence accueil familial et établissement","accueil familial agrément","combien coûte un accueil familial","Pouvez-vous définir l'accueil familial ?","À quoi correspond l'accueil familial ?","Je cherche une explication sur l'accueil familial : de quoi s'agit-il ?","C'est quoi l'accueil familial ?","Vous pouvez m'expliquer l'accueil familial ?","Comment présenter l'accueil familial à quelqu'un qui ne connaît pas le sujet ?","Pour une personne de mon entourage, qu'est-ce que l'accueil familial ?","Pouvez-vous répondre par oui ou non à la question suivante : Qu'est-ce que l'accueil familial ?","Question : qu'est-ce que l'accueil familial ?","Pourriez-vous me donner une définition de l'accueil familial ?"]},{"id":"CERT-MEDICAL-001","question":"Le certificat médical doit dater de combien ?","reponse":"Pour toute demande MDPH, le certificat médical joint au dossier doit dater de moins de 6 mois. Le dossier complet comprend aussi une photocopie recto verso d'un justificatif d'identité, un justificatif de domicile et, le cas échéant, une attestation de jugement de protection juridique. Un dossier incomplet retarde l'instruction de la demande.","source":{"titre":"Formulaire Cerfa 15692*01 — notice de demande MDPH","url":"https://www.formulaires.service-public.gouv.fr/gf/cerfa_15692.do"},"verifie_le":"2026-11-23","proprietaire":"Jeu de test factice (non validé MDA)","revue_avant":"2027-05-23","reformulations":["certificat médical mdph validité","durée validité certificat médical mdph","combien de temps certificat médical mdph","certificat médical périmé mdph","certificat médical de moins de combien de mois","pièces à joindre dossier mdph","quelles pièces pour un dossier mdph","le certificat médical a 8 mois est-il valable","Quelle est la durée de validité du certificat médical joint au dossier MDPH ?","Mon certificat médical a huit mois, il est encore bon ?","Le certificat médical MDPH doit avoir moins de combien de mois ?","Un certificat médical de plus d'un an est-il accepté par la MDPH ?","Quelle ancienneté maximale est tolérée pour le certificat médical ?","Jusqu'à quand le certificat médical rempli par mon médecin reste-t-il valable ?","Pour une demande MDPH, de quand doit être daté le certificat du médecin ?","Est-ce que je dois refaire faire mon certificat médical s'il date de l'an dernier ?","Le certificat médicale est valable combien de temps ?","Combien de mois maximum peuvent séparer la signature du certificat médical et le dépôt du dossier ?"]},{"id":"CIRCUIT-RECOURS-001","question":"Qui traite un recours gracieux à la MDA ?","reponse":"[Exemple FACTICE, non validé — à remplacer par le vrai circuit MDA] Un recours gracieux est en général réceptionné par le secrétariat de la CDAPH, puis instruit par le pôle évaluation ou le référent juridique avant un nouvel examen en commission. Le circuit exact propre à la MDA reste à documenter par le comité de validation.","source":{"titre":"Exemple fictif — aucune source réelle","url":""},"verifie_le":"2026-11-23","proprietaire":"FACTICE — ne reflète pas l'organisation réelle de la MDA","revue_avant":"2027-05-23","reformulations":["qui traite un recours gracieux","service qui gère les recours mdph","circuit recours gracieux mda","qui s'occupe des recours à la mda","quel pôle traite les recours","comment est examiné un recours gracieux en interne","qui reçoit les recours gracieux à l'accueil","quel service instruit un recours","Quel service examine le recours gracieux déposé auprès de la MDA ?","Mon recours gracieux, c'est qui qui le regarde ?","Qui se charge des recours gracieux adressés à la maison départementale de l'autonomie ?","Le recours gracieux est-il réexaminé par la CDAPH ?","Qui instruit les recours gracieux reçus par la MDA ?","Quelle équipe traite les contestations amiables à la MDPH ?","Une fois mon recours gracieux envoyé, qui va le réétudier ?","Est-ce que c'est la même équipe qui réexamine mon dossier après mon recours gracieux ?","Qui s'ocupe de mon recour gracieux ?","Quel est le circuit de traitement d'un recours gracieux au sein de la MDA ?"]},{"id":"SITUATION-INDIV-001","question":"Mon voisin a-t-il droit à l'AAH ?","reponse":"Je ne peux pas évaluer les droits d'une personne en particulier : cela relève d'une décision de la CDAPH, prise après instruction du dossier par la MDPH. Pour une situation individuelle, orientez la personne vers l'accueil de la MDPH ou invitez-la à déposer un dossier avec un certificat médical de moins de 6 mois.","source":{"titre":"Refus de principe — évaluation individuelle hors champ de l'outil","url":""},"verifie_le":"2026-11-23","proprietaire":"Jeu de test factice (non validé MDA)","revue_avant":"2027-05-23","reformulations":["mon voisin a droit à quoi","est-ce que telle personne a droit à l'aah","ma mère a-t-elle droit à la pch","mon fils peut il avoir l'aeeh","est ce que mon mari a droit à une pension d'invalidité","ai-je droit à l'aah dans mon cas précis","quel taux d'incapacité pour ma situation","va-t-on m'accorder la pch dans mon cas","Mon voisin pourrait-il toucher l'AAH ?","Ma voisine est malade, elle peut avoir l'AAH ou pas ?","Est-ce que mon collègue est éligible à l'allocation aux adultes handicapés ?","Mon beau-frère ne travaille plus depuis son accident, peut-il prétendre à l'AAH ?","Pouvez-vous me dire si mon voisin remplit les conditions pour l'AAH ?","D'après vous, mon ami a-t-il des chances d'obtenir l'AAH ?","Mon voisin a 45 ans et des problèmes de dos, il aurait l'AAH ?","Un de mes proches touche peu de revenus et a un handicap, est-ce qu'il obtiendrait l'AAH ?","Mon voisin peut il avoir l'AHH ?","Pour mon voisin qui est en fauteuil, l'AAH serait-elle accordée ?","Mon oncle a un certain taux d'incapacité, a-t-il droit à l'AAH ?","Ma tante a-t-elle droit à une aide vu son état de santé ?"]}];
